import React from 'react';
import { Loader2 } from 'lucide-react';

interface SpinnerProps {
  size?: 'sm' | 'md' | 'lg' | 'xl';
  className?: string;
  variant?: 'primary' | 'white' | 'slate' | 'indigo';
}

export const Spinner: React.FC<SpinnerProps> = ({ size = 'md', className = '', variant = 'primary' }) => {
  const sizeClasses = {
    sm: 'w-4 h-4',
    md: 'w-6 h-6',
    lg: 'w-10 h-10',
    xl: 'w-16 h-16'
  };

  const colorClasses = {
    primary: 'text-primary-600',
    white: 'text-white',
    slate: 'text-slate-400',
    indigo: 'text-indigo-600'
  };

  return (
    <Loader2 
      className={`animate-spin ${sizeClasses[size]} ${colorClasses[variant]} ${className}`} 
    />
  );
};

import React, { useState } from 'react';
import { dbService } from '../services/dbService';
import { SystemUser } from '../types';
import { User, Lock } from 'lucide-react';
import { Spinner } from './Spinner';

interface LoginProps {
  onLoginSuccess: (user: SystemUser) => void;
}

export const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [login, setLogin] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Simulate network delay for realism
    setTimeout(() => {
      // Use the new Authentication method against System Users DB
      const user = dbService.authenticateSystemUser(login, password);

      if (user) {
        onLoginSuccess(user);
      } else {
        setError('Acesso negado. Verifique suas credenciais.');
        setLoading(false);
