                            disabled={loading}
                            className="w-full bg-white border border-slate-300 rounded-lg px-4 py-3 pl-12 text-sm text-slate-700 placeholder-slate-400 outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all shadow-sm disabled:bg-slate-50"
                        />
