import React, { useState, useEffect, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { dbService } from '../services/dbService';
import { User } from '../types';
import { Users, Building2, TrendingUp } from 'lucide-react';
import { Spinner } from './Spinner';

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white p-3 border border-slate-200 shadow-lg rounded-lg">
        <p className="font-semibold text-slate-700">{label}</p>
        <p className="text-primary-600 font-bold">
          {payload[0].value} Colaboradores
        </p>
      </div>
    );
  }
  return null;
};

export const Dashboard: React.FC = () => {
  const [selectedFilial, setSelectedFilial] = useState<string>('TODAS');
  const [users, setUsers] = useState<User[]>([]);
  const [filialOptions, setFilialOptions] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Simulate Data Fetching
    const loadData = async () => {
        await new Promise(resolve => setTimeout(resolve, 800)); // Simulate delay
        setUsers(dbService.getAllUsers());
        setFilialOptions(dbService.getFiliais());
        setIsLoading(false);
    };
    loadData();
  }, []);

  const filteredUsers = useMemo(() => {
    if (selectedFilial === 'TODAS') return users;
    return users.filter(u => u.filial === selectedFilial);
  }, [selectedFilial, users]);

  const departmentData = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredUsers.forEach(u => {
      counts[u.departamento] = (counts[u.departamento] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [filteredUsers]);

  const sectorData = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredUsers.forEach(u => {
      counts[u.setor] = (counts[u.setor] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [filteredUsers]);

  const COLORS = ['#0ea5e9', '#ef4444', '#f59e0b', '#10b981', '#6366f1', '#8b5cf6'];

  if (isLoading) {
      return (
          <div className="flex h-full items-center justify-center min-h-[400px] animate-[fadeIn_0.3s]">
              <div className="flex flex-col items-center gap-4">
                  <Spinner size="lg" />
                  <p className="text-slate-400 text-sm font-medium animate-pulse">Carregando indicadores...</p>
              </div>
          </div>
      );
  }

  return (
    <div className="p-6 space-y-8 animate-[fadeIn_0.4s_ease-out]">

      <div className="flex flex-col md:flex-row justify-between items-end gap-4 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <div className="w-full md:w-1/3">
           <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
             <Building2 className="w-5 h-5 text-primary-500"/> 
             Filtro por Filial
           </h2>
           <div className="relative">
              <select
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl appearance-none focus:ring-2 focus:ring-primary-500 outline-none text-slate-700 font-medium"
                value={selectedFilial}
                onChange={(e) => {
                    setSelectedFilial(e.target.value);
                }}
              >
                <option value="TODAS">TODAS AS FILIAIS</option>
                {filialOptions.map(f => (
                  <option key={f} value={f}>{f}</option>
                ))}
              </select>
               <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
                  <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
              </div>
           </div>
        </div>

        <div className="flex gap-4">
           <div className="bg-blue-50 px-6 py-3 rounded-xl border border-blue-100">
              <p className="text-xs text-blue-600 font-bold uppercase tracking-wider">Total Colaboradores</p>
              <p className="text-2xl font-bold text-blue-900">{filteredUsers.length}</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-96">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
            <Users className="w-5 h-5 text-primary-500"/>
            Distribuição por Departamento
          </h3>
          <ResponsiveContainer width="100%" height="85%">
            <BarChart data={departmentData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10}} interval={0} />
              <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
              <Tooltip content={<CustomTooltip />} cursor={{fill: '#f1f5f9'}} />
              <Bar dataKey="value" radius={[4, 4, 0, 0]} animationDuration={1000}>
                {departmentData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-96">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-secondary-500"/>
            Distribuição por Setor
          </h3>
          <ResponsiveContainer width="100%" height="85%">
            <PieChart>
              <Pie
                data={sectorData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={100}
                paddingAngle={5}
                dataKey="value"
              >
                {sectorData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { User } from '../types';
import { Trash2, Search, Database, ShieldAlert, Edit2, Plus, X, Save, CheckCircle2, Eraser, AlertTriangle } from 'lucide-react';
import { Input } from './Input';
import { Select } from './Select';
import { Spinner } from './Spinner';

interface UsersListProps {
  onNavigateToRegister?: () => void;
}

export const UsersList: React.FC<UsersListProps> = ({ onNavigateToRegister }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  // Dynamic Options for Edit
  const [options, setOptions] = useState({
      filiais: [] as string[],
      departamentos: [] as string[],
      setores: [] as string[]
  });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  // Delete Modal State
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);
  const [isDeleteAll, setIsDeleteAll] = useState(false);

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  useEffect(() => {
    loadUsers();
    // Load options for the edit modal
    setOptions({
        filiais: dbService.getFiliais(),
        departamentos: dbService.getDepartamentos(),
        setores: dbService.getSetores()
    });
  }, []);

  const loadUsers = () => {
    setIsLoading(true);
    // Simulate DB fetch delay
    setTimeout(() => {
        setUsers(dbService.getAllUsers());
        setIsLoading(false);
    }, 600);
  };

  // Trigger Delete User Modal
  const confirmDeleteUser = (e: React.MouseEvent, user: User) => {
    e.stopPropagation();
    setUserToDelete(user);
    setIsDeleteAll(false);
    setIsDeleteModalOpen(true);
  };

  // Trigger Delete All Modal
  const confirmDeleteAll = () => {
    setUserToDelete(null);
    setIsDeleteAll(true);
    setIsDeleteModalOpen(true);
  };

  // Execute Deletion
  const handleExecuteDelete = () => {
    setIsProcessing(true);
    setTimeout(() => {
        if (isDeleteAll) {
            const result = dbService.deleteAllUsers();
            if (result.success) {
                setFeedback({ type: 'success', message: result.message });
                loadUsers();
            } else {
                setFeedback({ type: 'error', message: result.message });
            }
        } else if (userToDelete) {
            const result = dbService.deleteUser(userToDelete.id);
            if (result.success) {
                setFeedback({ type: 'success', message: result.message });
                loadUsers();
            } else {
                setFeedback({ type: 'error', message: result.message });
            }
        }

        // Close Modal and Clear feedback after 3s
        setIsProcessing(false);
        setIsDeleteModalOpen(false);
        setTimeout(() => setFeedback(null), 3000);
    }, 1000);
  };

  const handleEditClick = (user: User) => {
    setEditingUser({ ...user });
    setFeedback(null);
    setIsEditModalOpen(true);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editingUser) return;
    const { name, value } = e.target;
    let finalValue = value;
    if (['nomeCompleto', 'login'].includes(name)) {
        finalValue = value.toUpperCase();
    }
    setEditingUser({ ...editingUser, [name]: finalValue });
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;

    setIsProcessing(true);
    setTimeout(() => {
        const result = dbService.updateUser(editingUser);
        if (result.success) {
            setFeedback({ type: 'success', message: result.message });
            loadUsers();
            setIsEditModalOpen(false);
            setFeedback({ type: 'success', message: 'Usuário atualizado com sucesso!' });
            setTimeout(() => setFeedback(null), 3000);
        } else {
            setFeedback({ type: 'error', message: result.message });
        }
        setIsProcessing(false);
    }, 800);
  };

  // Optimized Search Logic using useMemo
  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) return users;

    return users.filter(user =>
      user.nomeCompleto.toLowerCase().includes(term) ||
      user.matricula.includes(term) ||
      user.filial.toLowerCase().includes(term) ||
      user.departamento.toLowerCase().includes(term) ||
      user.setor.toLowerCase().includes(term) ||
      user.login.toLowerCase().includes(term)
    );
  }, [users, searchTerm]);

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">

        {feedback && !isEditModalOpen && !isDeleteModalOpen && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            }`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <ShieldAlert className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 min-h-[500px]">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8">
                <div>
                    <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <Database className="w-6 h-6 text-primary-500"/>
                        Base de Dados de Usuários
                    </h2>
                    <p className="text-slate-500 text-sm mt-1">Gerenciamento completo dos registros do sistema</p>
                </div>

                <div className="flex gap-3 w-full md:w-auto flex-wrap md:flex-nowrap justify-end">
                    <div className="relative flex-1 md:w-56 group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
                        <input
                            type="text"
                            placeholder="Buscar por nome, setor..."
                            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all text-sm"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            disabled={isLoading}
                        />
                    </div>

                    {users.length > 0 && (
                        <button 
                            type="button"
                            onClick={confirmDeleteAll}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-red-50 text-red-600 border border-red-100 px-4 py-2.5 rounded-xl hover:bg-red-100 transition-colors font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Eraser className="w-4 h-4" />
                            Limpar Base
                        </button>
                    )}

                    {onNavigateToRegister && (
                        <button 
                            type="button"
                            onClick={onNavigateToRegister}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2.5 rounded-xl hover:bg-primary-700 transition-colors shadow-lg shadow-primary-500/20 font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Plus className="w-4 h-4" />
                            Novo Usuário
                        </button>
                    )}
                </div>
            </div>

            <div className="overflow-hidden rounded-xl border border-slate-200 shadow-sm">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-slate-50/50 border-b border-slate-200">
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Matrícula</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Nome Completo</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Filial</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Departamento / Setor</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Login</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider text-right">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                        {isLoading ? (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                     <div className="flex flex-col items-center justify-center gap-3">
                                        <Spinner size="lg" />
                                        <p className="text-slate-400 font-medium">Carregando registros...</p>
                                     </div>
                                </td>
                            </tr>
                        ) : filteredUsers.length > 0 ? (
                            filteredUsers.map((user) => (
                                <tr key={user.id} className="hover:bg-slate-50/80 transition-colors group">
                                    <td className="p-4 text-sm text-slate-600 font-mono font-medium">{user.matricula}</td>
                                    <td className="p-4">
                                        <div className="font-semibold text-slate-800 text-sm">{user.nomeCompleto}</div>
                                        <div className="text-xs text-slate-400">Cadastrado em {new Date(user.dataCadastro).toLocaleDateString()}</div>
                                    </td>
                                    <td className="p-4">
                                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-50 text-blue-700 border border-blue-100">
                                            {user.filial}
                                        </span>
                                    </td>
                                    <td className="p-4">
                                        <div className="text-sm text-slate-700">{user.departamento}</div>
                                        <div className="text-xs text-slate-500">{user.setor}</div>
                                    </td>
                                    <td className="p-4 text-sm text-slate-600 font-mono bg-slate-50/50 rounded w-fit px-2">{user.login}</td>
                                    <td className="p-4 text-right">
                                        <div className="flex items-center justify-end gap-2">
                                            <button 
                                                type="button"
                                                onClick={() => handleEditClick(user)} 
                                                className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all" 
                                                title="Editar"
                                            >
                                                <Edit2 className="w-4 h-4" />
                                            </button>
                                            <button 
                                                type="button"
                                                onClick={(e) => confirmDeleteUser(e, user)} 
                                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all" 
                                                title="Excluir"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                    <div className="flex flex-col items-center justify-center text-slate-400">
                                        <ShieldAlert className="w-12 h-12 mb-3 text-slate-300" />
                                        <p className="text-lg font-medium text-slate-500">Nenhum registro encontrado</p>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <div className="mt-4 flex justify-between items-center text-xs text-slate-400 border-t border-slate-100 pt-4">
                <p>Mostrando {filteredUsers.length} de {users.length} registros</p>
            </div>
        </div>

        {/* Edit Modal */}
        {isEditModalOpen && editingUser && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s]">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                        <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                            <Edit2 className="w-5 h-5 text-primary-600"/>
                            Editar Usuário
                        </h3>
                        <button onClick={() => setIsEditModalOpen(false)} disabled={isProcessing} className="text-slate-400 hover:text-slate-600 transition-colors disabled:opacity-50">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <form onSubmit={handleSaveEdit} className="p-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <Input label="Matrícula" name="matricula" value={editingUser.matricula} onChange={handleEditChange} required disabled={isProcessing} />
                            <Select label="Filial" name="filial" value={editingUser.filial} onChange={handleEditChange} options={options.filiais} required disabled={isProcessing} />
                            <div className="col-span-1 md:col-span-2">
                                <Input label="Nome Completo" name="nomeCompleto" value={editingUser.nomeCompleto} onChange={handleEditChange} required disabled={isProcessing} />
                            </div>
                            <Input label="Login" name="login" value={editingUser.login} onChange={handleEditChange} required disabled={isProcessing} />
                            <Input label="Senha" name="senha" type="password" value={editingUser.senha || ''} onChange={handleEditChange} required disabled={isProcessing} />
                            <Select label="Departamento" name="departamento" value={editingUser.departamento} onChange={handleEditChange} options={options.departamentos} required disabled={isProcessing} />
                            <Select label="Setor" name="setor" value={editingUser.setor} onChange={handleEditChange} options={options.setores} required disabled={isProcessing} />
                        </div>
                        <div className="mt-6 flex justify-end gap-3">
                            <button type="button" onClick={() => setIsEditModalOpen(false)} disabled={isProcessing} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors font-medium disabled:opacity-50">Cancelar</button>
                            <button type="submit" disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors font-medium shadow-lg shadow-primary-500/20 disabled:opacity-70 disabled:cursor-not-allowed">
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Save className="w-4 h-4" />}
                                {isProcessing ? 'Salvando...' : 'Salvar Alterações'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* Delete Confirmation Modal */}
        {isDeleteModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s]">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertTriangle className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Confirmar Exclusão</h3>
                        <p className="text-slate-500 mb-6">
                            {isDeleteAll 
                                ? "Você está prestes a excluir TODOS os registros da base de dados. Esta ação é irreversível." 
                                : `Tem certeza que deseja excluir o usuário ${userToDelete?.nomeCompleto} (Login: ${userToDelete?.login})?`
                            }
                        </p>

                        <div className="flex gap-3 justify-center">
                            <button 
                                onClick={() => setIsDeleteModalOpen(false)}
                                disabled={isProcessing}
                                className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium disabled:opacity-50"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={handleExecuteDelete}
                                disabled={isProcessing}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors font-medium shadow-lg shadow-red-500/30 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Trash2 className="w-4 h-4" />}
                                {isProcessing ? "Processando..." : (isDeleteAll ? "Sim, Limpar Tudo" : "Sim, Excluir")}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/dbService';
import { Input } from './Input';
import { Select } from './Select';
import { Save, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Spinner } from './Spinner';

export const RegisterUser: React.FC = () => {
  const [formData, setFormData] = useState({
    matricula: '',
    nomeCompleto: '',
    filial: '',
    login: '',
    senha: '',
    departamento: '',
    setor: ''
  });

  const [isSaving, setIsSaving] = useState(false);

  // Dynamic Options States
  const [options, setOptions] = useState({
      filiais: [] as string[],
      departamentos: [] as string[],
      setores: [] as string[]
  });

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [fieldErrors, setFieldErrors] = useState<{ matricula?: string }>({});

  useEffect(() => {
    // Load dynamic options from DB
    setOptions({
        filiais: dbService.getFiliais(),
        departamentos: dbService.getDepartamentos(),
        setores: dbService.getSetores()
    });
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    // Apply Uppercase constraints immediately
    let finalValue = value;
    if (['nomeCompleto', 'login'].includes(name)) {
        finalValue = value.toUpperCase();
    }

    setFormData(prev => ({ ...prev, [name]: finalValue }));

    // Clear field specific error when user starts typing again
    if (name === 'matricula') {
        setFieldErrors(prev => ({ ...prev, matricula: undefined }));
    }

    if (feedback) setFeedback(null);
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      const { name, value } = e.target;
      if (name === 'matricula' && value) {
          const exists = dbService.checkMatriculaExists(value);
          if (exists) {
              setFieldErrors(prev => ({ ...prev, matricula: `A matrícula ${value} já está cadastrada no sistema.` }));
          }
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (Object.values(formData).some(x => x === '')) {
        setFeedback({ type: 'error', message: 'Por favor, preencha todos os campos.' });
        return;
    }

    if (fieldErrors.matricula) {
        setFeedback({ type: 'error', message: 'Corrija os erros do formulário antes de salvar.' });
        return;
    }

    setIsSaving(true);
    // Simulate API delay
    setTimeout(() => {
        const result = dbService.addUser({
            ...formData
        });

        if (result.success) {
            setFeedback({ type: 'success', message: result.message });
            setFormData({
                matricula: '',
                nomeCompleto: '',
                filial: '',
                login: '',
                senha: '',
                departamento: '',
                setor: ''
            });
        } else {
            setFeedback({ type: 'error', message: result.message });
        }
        setIsSaving(false);
    }, 1000);
  };

  return (
    <div className="max-w-4xl mx-auto p-6 animate-[fadeIn_0.3s_ease-out]">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
        <div className="bg-gradient-to-r from-slate-900 to-slate-800 p-6 flex items-center justify-between">
            <div>
                <h2 className="text-2xl font-bold text-white">Novo Colaborador</h2>
                <p className="text-slate-400 text-sm mt-1">Preencha os dados abaixo para cadastrar um novo usuário no sistema.</p>
            </div>
            <div className="hidden sm:block text-right">
                <p className="text-slate-400 text-xs uppercase tracking-wider">Data do Cadastro</p>
                <p className="text-white font-mono">{new Date().toLocaleDateString()}</p>
            </div>
        </div>

        <form onSubmit={handleSubmit} className="p-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

                {/* ID and Branch Row */}
                <div className="col-span-1">
                    <Input 
                        label="Matrícula"
                        name="matricula"
                        type="number"
                        placeholder="Ex: 1005"
                        value={formData.matricula}
                        onChange={handleChange}
                        onBlur={handleBlur}
                        error={fieldErrors.matricula}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                     <Select
                        label="Filial"
                        name="filial"
                        value={formData.filial}
                        onChange={handleChange}
                        options={options.filiais}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Name Row */}
                <div className="col-span-1 md:col-span-2">
                    <Input 
                        label="Nome Completo (Automático Caixa Alta)"
                        name="nomeCompleto"
                        type="text"
                        placeholder="NOME DO FUNCIONÁRIO"
                        value={formData.nomeCompleto}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Login Info */}
                <div className="col-span-1">
                    <Input 
                        label="Login (Automático Caixa Alta)"
                        name="login"
                        type="text"
                        placeholder="USUARIO.LOGIN"
                        value={formData.login}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                    <Input 
                        label="Senha"
                        name="senha"
                        type="password"
                        placeholder="••••••••"
                        value={formData.senha}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Job Info */}
                <div className="col-span-1">
                    <Select
                        label="Departamento"
                        name="departamento"
                        value={formData.departamento}
                        onChange={handleChange}
                        options={options.departamentos}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                     <Select
                        label="Setor"
                        name="setor"
                        value={formData.setor}
                        onChange={handleChange}
                        options={options.setores}
                        required
                        disabled={isSaving}
                    />
                </div>
            </div>

            {/* Feedback Message */}
            {feedback && (
                <div className={`mt-6 p-4 rounded-lg flex items-center gap-3 ${feedback.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                    {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                    <span className="font-medium">{feedback.message}</span>
                </div>
            )}

            <div className="mt-8 flex justify-end">
                <button 
                    type="submit"
                    disabled={isSaving}
                    className="flex items-center gap-2 bg-primary-600 text-white px-8 py-3 rounded-xl hover:bg-primary-700 active:scale-95 transition-all shadow-lg shadow-primary-500/30 font-semibold disabled:opacity-70 disabled:cursor-not-allowed"
                >
                    {isSaving ? <Spinner size="sm" variant="white" /> : <Save className="w-5 h-5" />}
                    {isSaving ? 'Salvando...' : 'Salvar Cadastro'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Input } from './Input';
import { Select } from './Select';
import { Database, Server, Save, Activity, CheckCircle2, XCircle } from 'lucide-react';
import { Spinner } from './Spinner';

export const DatabaseSettings: React.FC = () => {
  const [config, setConfig] = useState({
    type: '',
    host: '',
    port: '',
    database: '',
    user: '',
    password: ''
  });

  const [status, setStatus] = useState<'DISCONNECTED' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');
  const [lastCheck, setLastCheck] = useState<string | null>(null);

  // Load saved config on mount
  useEffect(() => {
    const saved = localStorage.getItem('k_system_db_config');
    if (saved) {
      setConfig(JSON.parse(saved));
      // Optionally simulate that we are already connected if config exists
      setStatus('CONNECTED');
      setLastCheck(new Date().toLocaleTimeString());
    }
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setConfig({ ...config, [e.target.name]: e.target.value });
    if (status === 'CONNECTED' || status === 'ERROR') {
        setStatus('DISCONNECTED'); // Reset status on change
    }
  };

  const handleTestConnection = (e: React.FormEvent) => {
    e.preventDefault();

    if (!config.type || !config.host || !config.user) {
        setStatus('ERROR');
        return;
    }

    setStatus('CONNECTING');

    // Simulate network request
    setTimeout(() => {
        // Simple mock validation logic
        if (config.host.includes('.') || config.host === 'localhost') {
            setStatus('CONNECTED');
            setLastCheck(new Date().toLocaleTimeString());
            localStorage.setItem('k_system_db_config', JSON.stringify(config));
        } else {
            setStatus('ERROR');
        }
    }, 2000);
  };

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="bg-slate-900 p-6 flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        <Server className="w-6 h-6 text-primary-400"/>
                        Configuração de Conexão
                    </h2>
                    <p className="text-slate-400 text-sm mt-1">Gerencie a conexão com o banco de dados externo.</p>
                </div>
                <div className="hidden sm:flex items-center gap-3 bg-slate-800 px-4 py-2 rounded-lg border border-slate-700">
                    <div className="text-right">
                        <p className="text-xs text-slate-400 uppercase tracking-wider font-semibold">Status Atual</p>
                        <p className={`text-sm font-bold flex items-center justify-end gap-1.5 ${
                            status === 'CONNECTED' ? 'text-green-400' : 
                            status === 'CONNECTING' ? 'text-yellow-400' : 
                            status === 'ERROR' ? 'text-red-400' : 'text-slate-500'
                        }`}>
                            {status === 'CONNECTED' && <CheckCircle2 className="w-4 h-4" />}
                            {status === 'ERROR' && <XCircle className="w-4 h-4" />}
                            {status === 'CONNECTING' && <Spinner size="sm" variant="white" />}
                            {status === 'DISCONNECTED' && <Activity className="w-4 h-4" />}
                            {status === 'CONNECTED' ? 'CONECTADO' : 
                             status === 'CONNECTING' ? 'CONECTANDO...' : 
                             status === 'ERROR' ? 'FALHA NA CONEXÃO' : 'DESCONECTADO'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="p-8">
                <form onSubmit={handleTestConnection}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                        <div className="col-span-1 md:col-span-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Parâmetros do Servidor
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Select 
                                label="Tipo de Banco de Dados"
                                name="type"
                                options={['MySQL', 'PostgreSQL', 'Oracle', 'SQL Server', 'MariaDB']}
                                value={config.type}
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Nome da Base (Database)"
                                name="database"
                                placeholder="ex: k_system_prod"
                                value={config.database}
                                onChange={handleChange}
                            />
                        </div>

                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Host / IP"
                                name="host"
                                placeholder="ex: 192.168.1.50"
                                value={config.host}
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Porta"
                                name="port"
                                placeholder="ex: 3306"
                                value={config.port}
                                onChange={handleChange}
                                type="number"
                            />
                        </div>

                        <div className="col-span-1 md:col-span-2 mt-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Credenciais de Acesso
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Input 
                                label="Usuário"
                                name="user"
                                placeholder="root"
                                value={config.user}
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Senha"
                                name="password"
                                type="password"
                                placeholder="••••••••"
                                value={config.password}
                                onChange={handleChange}
                            />
                        </div>
                    </div>

                    <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                        <div className="text-xs text-slate-400">
                            {lastCheck && <span>Última verificação: {lastCheck}</span>}
                        </div>
                        <div className="flex gap-3">
                            <button
                                type="button" 
                                onClick={() => {
                                    setConfig({ type: '', host: '', port: '', database: '', user: '', password: '' });
                                    setStatus('DISCONNECTED');
                                    localStorage.removeItem('k_system_db_config');
                                }}
                                className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-xl transition-colors"
                            >
                                Limpar
                            </button>
                            <button 
                                type="submit"
                                disabled={status === 'CONNECTING'}
                                className={`
                                    flex items-center gap-2 px-8 py-2.5 bg-primary-600 text-white rounded-xl font-semibold shadow-lg shadow-primary-500/30 hover:bg-primary-700 transition-all active:scale-95
                                    ${status === 'CONNECTING' ? 'opacity-70 cursor-not-allowed' : ''}
                                `}
                            >
                                {status === 'CONNECTING' ? (
                                    <>
                                        <Spinner size="sm" variant="white" />
                                        <span>Verificando...</span>
                                    </>
                                ) : (
                                    <>
                                        <Save className="w-5 h-5" />
                                        Salvar e Conectar
                                    </>
                                )}
                            </button>
                        </div>
                    </div>
                </form>
            </div>
        </div>

        {/* Info Card */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-blue-50 border border-blue-100 p-6 rounded-xl flex items-start gap-4">
                <Database className="w-8 h-8 text-blue-500 shrink-0" />
                <div>
                    <h4 className="font-bold text-blue-900 mb-1">Modo Híbrido</h4>
                    <p className="text-sm text-blue-700 leading-relaxed">
                        O sistema operará em modo offline (Local Storage) caso a conexão com o servidor falhe.
                    </p>
                </div>
            </div>
            <div className="bg-slate-50 border border-slate-200 p-6 rounded-xl flex items-start gap-4 md:col-span-2">
                <Server className="w-8 h-8 text-slate-400 shrink-0" />
                <div>
                    <h4 className="font-bold text-slate-800 mb-1">Requisitos de Rede</h4>
                    <p className="text-sm text-slate-600 leading-relaxed">
                        Certifique-se que o IP deste terminal está liberado no Firewall do servidor de banco de dados.
                        Conexões via SSL são recomendadas para ambientes de produção.
                    </p>
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { User } from '../types';
import { Trash2, Search, Database, ShieldAlert, Edit2, Plus, X, Save, CheckCircle2, Eraser, AlertTriangle } from 'lucide-react';
import { Input } from './Input';
import { Select } from './Select';
import { Spinner } from './Spinner';

interface UsersListProps {
  onNavigateToRegister?: () => void;
}

export const UsersList: React.FC<UsersListProps> = ({ onNavigateToRegister }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  // Dynamic Options for Edit
  const [options, setOptions] = useState({
      filiais: [] as string[],
      departamentos: [] as string[],
      setores: [] as string[]
  });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  // Delete Modal State
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);
  const [isDeleteAll, setIsDeleteAll] = useState(false);

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  useEffect(() => {
    loadUsers();
    // Load options for the edit modal
    setOptions({
        filiais: dbService.getFiliais(),
        departamentos: dbService.getDepartamentos(),
        setores: dbService.getSetores()
    });
  }, []);

  const loadUsers = () => {
    setIsLoading(true);
    // Simulate DB fetch delay
    setTimeout(() => {
        setUsers(dbService.getAllUsers());
        setIsLoading(false);
    }, 600);
  };

  // Trigger Delete User Modal
  const confirmDeleteUser = (e: React.MouseEvent, user: User) => {
    e.stopPropagation();
    setUserToDelete(user);
    setIsDeleteAll(false);
    setIsDeleteModalOpen(true);
  };

  // Trigger Delete All Modal
  const confirmDeleteAll = () => {
    setUserToDelete(null);
    setIsDeleteAll(true);
    setIsDeleteModalOpen(true);
  };

  // Execute Deletion
  const handleExecuteDelete = () => {
    setIsProcessing(true);
    setTimeout(() => {
        if (isDeleteAll) {
            const result = dbService.deleteAllUsers();
            if (result.success) {
                setFeedback({ type: 'success', message: result.message });
                loadUsers();
            } else {
                setFeedback({ type: 'error', message: result.message });
            }
        } else if (userToDelete) {
            const result = dbService.deleteUser(userToDelete.id);
            if (result.success) {
                setFeedback({ type: 'success', message: result.message });
                loadUsers();
            } else {
                setFeedback({ type: 'error', message: result.message });
            }
        }

        // Close Modal and Clear feedback after 3s
        setIsProcessing(false);
        setIsDeleteModalOpen(false);
        setTimeout(() => setFeedback(null), 3000);
    }, 1000);
  };

  const handleEditClick = (user: User) => {
    setEditingUser({ ...user });
    setFeedback(null);
    setIsEditModalOpen(true);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editingUser) return;
    const { name, value } = e.target;
    let finalValue = value;
    if (['nomeCompleto', 'login'].includes(name)) {
        finalValue = value.toUpperCase();
    }
    setEditingUser({ ...editingUser, [name]: finalValue });
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;

    setIsProcessing(true);
    setTimeout(() => {
        const result = dbService.updateUser(editingUser);
        if (result.success) {
            setFeedback({ type: 'success', message: result.message });
            loadUsers();
            setIsEditModalOpen(false);
            setFeedback({ type: 'success', message: 'Usuário atualizado com sucesso!' });
            setTimeout(() => setFeedback(null), 3000);
        } else {
            setFeedback({ type: 'error', message: result.message });
        }
        setIsProcessing(false);
    }, 800);
  };

  // Optimized Search Logic using useMemo
  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) return users;

    return users.filter(user =>
      user.nomeCompleto.toLowerCase().includes(term) ||
      user.matricula.includes(term) ||
      user.filial.toLowerCase().includes(term) ||
      user.departamento.toLowerCase().includes(term) ||
      user.setor.toLowerCase().includes(term) ||
      user.login.toLowerCase().includes(term)
    );
  }, [users, searchTerm]);

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">

        {feedback && !isEditModalOpen && !isDeleteModalOpen && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            }`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <ShieldAlert className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 min-h-[500px]">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8">
                <div>
                    <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <Database className="w-6 h-6 text-primary-500"/>
                        Base de Dados de Usuários
                    </h2>
                    <p className="text-slate-500 text-sm mt-1">Gerenciamento completo dos registros do sistema</p>
                </div>

                <div className="flex gap-3 w-full md:w-auto flex-wrap md:flex-nowrap justify-end">
                    <div className="relative flex-1 md:w-80 group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
                        <input
                            type="text"
                            placeholder="Buscar por matrícula, nome, filial, login..."
                            className="w-full pl-10 pr-10 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all text-sm"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            disabled={isLoading}
                        />
                        {searchTerm && (
                            <button 
                                onClick={() => setSearchTerm('')}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 rounded-full hover:bg-slate-200 transition-colors"
                                title="Limpar busca"
                            >
                                <X className="w-3 h-3" />
                            </button>
                        )}
                    </div>

                    {users.length > 0 && (
                        <button 
                            type="button"
                            onClick={confirmDeleteAll}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-red-50 text-red-600 border border-red-100 px-4 py-2.5 rounded-xl hover:bg-red-100 transition-colors font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Eraser className="w-4 h-4" />
                            Limpar Base
                        </button>
                    )}

                    {onNavigateToRegister && (
                        <button 
                            type="button"
                            onClick={onNavigateToRegister}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2.5 rounded-xl hover:bg-primary-700 transition-colors shadow-lg shadow-primary-500/20 font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Plus className="w-4 h-4" />
                            Novo Usuário
                        </button>
                    )}
                </div>
            </div>

            <div className="overflow-hidden rounded-xl border border-slate-200 shadow-sm">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-slate-50/50 border-b border-slate-200">
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Matrícula</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Nome Completo</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Filial</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Departamento / Setor</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider">Login</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider text-right">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                        {isLoading ? (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                     <div className="flex flex-col items-center justify-center gap-3">
                                        <Spinner size="lg" />
                                        <p className="text-slate-400 font-medium">Carregando registros...</p>
                                     </div>
                                </td>
                            </tr>
                        ) : filteredUsers.length > 0 ? (
                            filteredUsers.map((user) => (
                                <tr key={user.id} className="hover:bg-slate-50/80 transition-colors group">
                                    <td className="p-4 text-sm text-slate-600 font-mono font-medium">{user.matricula}</td>
                                    <td className="p-4">
                                        <div className="font-semibold text-slate-800 text-sm">{user.nomeCompleto}</div>
                                        <div className="text-xs text-slate-400">Cadastrado em {new Date(user.dataCadastro).toLocaleDateString()}</div>
                                    </td>
                                    <td className="p-4">
                                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-50 text-blue-700 border border-blue-100">
                                            {user.filial}
                                        </span>
                                    </td>
                                    <td className="p-4">
                                        <div className="text-sm text-slate-700">{user.departamento}</div>
                                        <div className="text-xs text-slate-500">{user.setor}</div>
                                    </td>
                                    <td className="p-4 text-sm text-slate-600 font-mono bg-slate-50/50 rounded w-fit px-2">{user.login}</td>
                                    <td className="p-4 text-right">
                                        <div className="flex items-center justify-end gap-2">
                                            <button 
                                                type="button"
                                                onClick={() => handleEditClick(user)} 
                                                className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all" 
                                                title="Editar"
                                            >
                                                <Edit2 className="w-4 h-4" />
                                            </button>
                                            <button 
                                                type="button"
                                                onClick={(e) => confirmDeleteUser(e, user)} 
                                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all" 
                                                title="Excluir"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                    <div className="flex flex-col items-center justify-center text-slate-400">
                                        <ShieldAlert className="w-12 h-12 mb-3 text-slate-300" />
                                        <p className="text-lg font-medium text-slate-500">
                                            {searchTerm ? `Nenhum resultado para "${searchTerm}"` : 'Nenhum registro encontrado'}
                                        </p>
                                        {searchTerm && (
                                            <button 
                                                onClick={() => setSearchTerm('')}
                                                className="mt-2 text-primary-600 hover:text-primary-700 text-sm font-medium hover:underline"
                                            >
                                                Limpar filtros
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <div className="mt-4 flex justify-between items-center text-xs text-slate-400 border-t border-slate-100 pt-4">
                <p>Mostrando {filteredUsers.length} de {users.length} registros</p>
            </div>
        </div>

        {/* Edit Modal */}
        {isEditModalOpen && editingUser && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s]">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                        <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                            <Edit2 className="w-5 h-5 text-primary-600"/>
                            Editar Usuário
                        </h3>
                        <button onClick={() => setIsEditModalOpen(false)} disabled={isProcessing} className="text-slate-400 hover:text-slate-600 transition-colors disabled:opacity-50">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <form onSubmit={handleSaveEdit} className="p-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <Input label="Matrícula" name="matricula" value={editingUser.matricula} onChange={handleEditChange} required disabled={isProcessing} />
                            <Select label="Filial" name="filial" value={editingUser.filial} onChange={handleEditChange} options={options.filiais} required disabled={isProcessing} />
                            <div className="col-span-1 md:col-span-2">
                                <Input label="Nome Completo" name="nomeCompleto" value={editingUser.nomeCompleto} onChange={handleEditChange} required disabled={isProcessing} />
                            </div>
                            <Input label="Login" name="login" value={editingUser.login} onChange={handleEditChange} required disabled={isProcessing} />
                            <Input label="Senha" name="senha" type="password" value={editingUser.senha || ''} onChange={handleEditChange} required disabled={isProcessing} />
                            <Select label="Departamento" name="departamento" value={editingUser.departamento} onChange={handleEditChange} options={options.departamentos} required disabled={isProcessing} />
                            <Select label="Setor" name="setor" value={editingUser.setor} onChange={handleEditChange} options={options.setores} required disabled={isProcessing} />
                        </div>
                        <div className="mt-6 flex justify-end gap-3">
                            <button type="button" onClick={() => setIsEditModalOpen(false)} disabled={isProcessing} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors font-medium disabled:opacity-50">Cancelar</button>
                            <button type="submit" disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors font-medium shadow-lg shadow-primary-500/20 disabled:opacity-70 disabled:cursor-not-allowed">
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Save className="w-4 h-4" />}
                                {isProcessing ? 'Salvando...' : 'Salvar Alterações'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* Delete Confirmation Modal */}
        {isDeleteModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s]">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertTriangle className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Confirmar Exclusão</h3>
                        <p className="text-slate-500 mb-6">
                            {isDeleteAll 
                                ? "Você está prestes a excluir TODOS os registros da base de dados. Esta ação é irreversível." 
                                : `Tem certeza que deseja excluir o usuário ${userToDelete?.nomeCompleto} (Login: ${userToDelete?.login})?`
                            }
                        </p>

                        <div className="flex gap-3 justify-center">
                            <button 
                                onClick={() => setIsDeleteModalOpen(false)}
                                disabled={isProcessing}
                                className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium disabled:opacity-50"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={handleExecuteDelete}
                                disabled={isProcessing}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors font-medium shadow-lg shadow-red-500/30 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Trash2 className="w-4 h-4" />}
                                {isProcessing ? "Processando..." : (isDeleteAll ? "Sim, Limpar Tudo" : "Sim, Excluir")}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState } from 'react';
import { ViewState, SystemUser } from './types';
