      const newUser: SystemUser = {
          ...user,
          id: crypto.randomUUID(),
          createdAt: new Date().toISOString()
      };

      users.push(newUser);
      localStorage.setItem(SYSTEM_USERS_KEY, JSON.stringify(users));
      return { success: true, message: 'Usuário de sistema criado com sucesso.' };
  },

  deleteSystemUser: (id: string): { success: boolean; message: string } => {
      const users = dbService.getSystemUsers();
      if (users.length <= 1) return { success: false, message: 'Não é possível excluir o único usuário do sistema.' };

      const newUsers = users.filter(u => String(u.id) !== String(id));
      if (newUsers.length === users.length) return { success: false, message: 'Usuário não encontrado.' };

      localStorage.setItem(SYSTEM_USERS_KEY, JSON.stringify(newUsers));
      return { success: true, message: 'Acesso revogado com sucesso.' };
  },

  authenticateSystemUser: (login: string, password: string): SystemUser | null => {
      const users = dbService.getSystemUsers();
      // Case insensitive login
      const user = users.find(u => u.login.toUpperCase() === login.toUpperCase() && u.senha === password);
      return user || null;
  },


  // --- EMPLOYEES / COLLABORATORS (OLD USERS) ---
  getAllUsers: (): User[] => {
    const stored = localStorage.getItem(DB_KEY);
    if (!stored) {
      localStorage.setItem(DB_KEY, JSON.stringify(INITIAL_USERS));
      return INITIAL_USERS;
    }
    return JSON.parse(stored);
  },

  // Helper for realtime login validation
  checkLoginExists: (login: string): boolean => {
      const users = dbService.getAllUsers();
      return users.some(u => u.login === login);
  },

  addUser: (user: Omit<User, 'id' | 'dataCadastro'>): { success: boolean; message: string } => {
    const users = dbService.getAllUsers();

    // Removed Matricula Check

    // Check for unique login
    if (users.some(u => u.login === user.login)) {
      return { success: false, message: `Erro: O login ${user.login} já está em uso por outro colaborador.` };
    }
    const newUser: User = {
      ...user,
      id: crypto.randomUUID(),
      dataCadastro: new Date().toISOString()
    };
    users.push(newUser);
    localStorage.setItem(DB_KEY, JSON.stringify(users));
    return { success: true, message: 'Usuário cadastrado com sucesso!' };
  },

  updateUser: (updatedUser: User): { success: boolean; message: string } => {
    const users = dbService.getAllUsers();
    const index = users.findIndex(u => u.id === updatedUser.id);
    if (index === -1) return { success: false, message: 'Usuário não encontrado.' };

    // Removed existingMatricula Check

    const existingLogin = users.find(u => u.login === updatedUser.login && u.id !== updatedUser.id);
    if (existingLogin) return { success: false, message: `O login ${updatedUser.login} já está em uso.` };

    users[index] = updatedUser;
    localStorage.setItem(DB_KEY, JSON.stringify(users));
    return { success: true, message: 'Usuário atualizado com sucesso!' };
  },

  deleteUser: (id: string): { success: boolean; message: string } => {
    const users = dbService.getAllUsers();
    // Use String conversion for safer comparison in case of legacy number IDs
    const newUsers = users.filter(u => String(u.id) !== String(id));

    if (users.length === newUsers.length) return { success: false, message: 'Erro: Usuário não encontrado para exclusão.' };

    localStorage.setItem(DB_KEY, JSON.stringify(newUsers));
    return { success: true, message: 'Usuário excluído com sucesso.' };
  },

  deleteAllUsers: (): { success: boolean; message: string } => {
    localStorage.setItem(DB_KEY, '[]');
    return { success: true, message: 'Base de dados limpa com sucesso.' };
  },

  // --- FILIAIS ---
  getFiliais: () => getList(KEYS.FILIAIS, DEFAULTS.FILIAIS),
  addFilial: (name: string) => addToList(KEYS.FILIAIS, name),
  deleteFilial: (name: string) => removeFromList(KEYS.FILIAIS, name),

  // --- DEPARTAMENTOS ---
  getDepartamentos: () => getList(KEYS.DEPARTAMENTOS, DEFAULTS.DEPARTAMENTOS),
  addDepartamento: (name: string) => addToList(KEYS.DEPARTAMENTOS, name),
  deleteDepartamento: (name: string) => removeFromList(KEYS.DEPARTAMENTOS, name),

  // --- SETORES ---
  getSetores: () => getList(KEYS.SETORES, DEFAULTS.SETORES),
  addSetor: (name: string) => addToList(KEYS.SETORES, name),
  deleteSetor: (name: string) => removeFromList(KEYS.SETORES, name),
};

import React, { useState, useEffect, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { User } from '../types';
import { Trash2, Search, Database, ShieldAlert, Edit2, Plus, X, Save, CheckCircle2, Eraser, AlertTriangle, Printer } from 'lucide-react';
import { Input } from './Input';
import { Select } from './Select';
import { Spinner } from './Spinner';

interface UsersListProps {
  onNavigateToRegister?: () => void;
}

export const UsersList: React.FC<UsersListProps> = ({ onNavigateToRegister }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  // Dynamic Options for Edit
  const [options, setOptions] = useState({
      filiais: [] as string[],
      departamentos: [] as string[],
      setores: [] as string[]
  });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  // Delete Modal State
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);
  const [isDeleteAll, setIsDeleteAll] = useState(false);

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  useEffect(() => {
    loadUsers();
    // Load options for the edit modal
    setOptions({
        filiais: dbService.getFiliais(),
        departamentos: dbService.getDepartamentos(),
        setores: dbService.getSetores()
    });
  }, []);

  const loadUsers = () => {
    setIsLoading(true);
    // Simulate DB fetch delay
    setTimeout(() => {
        setUsers(dbService.getAllUsers());
        setIsLoading(false);
    }, 600);
  };

  const handlePrint = () => {
      window.print();
  };

  // Trigger Delete User Modal
  const confirmDeleteUser = (e: React.MouseEvent, user: User) => {
    e.stopPropagation();
    setUserToDelete(user);
    setIsDeleteAll(false);
    setIsDeleteModalOpen(true);
  };

  // Trigger Delete All Modal
  const confirmDeleteAll = () => {
    setUserToDelete(null);
    setIsDeleteAll(true);
    setIsDeleteModalOpen(true);
  };

  // Execute Deletion
  const handleExecuteDelete = () => {
    setIsProcessing(true);
    setTimeout(() => {
        if (isDeleteAll) {
            const result = dbService.deleteAllUsers();
            if (result.success) {
                setFeedback({ type: 'success', message: result.message });
                loadUsers();
            } else {
                setFeedback({ type: 'error', message: result.message });
            }
        } else if (userToDelete) {
            const result = dbService.deleteUser(userToDelete.id);
            if (result.success) {
                setFeedback({ type: 'success', message: result.message });
                loadUsers();
            } else {
                setFeedback({ type: 'error', message: result.message });
            }
        }

        // Close Modal and Clear feedback after 3s
        setIsProcessing(false);
        setIsDeleteModalOpen(false);
        setTimeout(() => setFeedback(null), 3000);
    }, 1000);
  };

  const handleEditClick = (user: User) => {
    setEditingUser({ ...user });
    setFeedback(null);
    setIsEditModalOpen(true);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (!editingUser) return;
    const { name, value } = e.target;
    let finalValue = value;
    if (['nomeCompleto', 'login'].includes(name)) {
        finalValue = value.toUpperCase();
    }
    setEditingUser({ ...editingUser, [name]: finalValue });
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;

    setIsProcessing(true);
    setTimeout(() => {
        const result = dbService.updateUser(editingUser);
        if (result.success) {
            setFeedback({ type: 'success', message: result.message });
            loadUsers();
            setIsEditModalOpen(false);
            setFeedback({ type: 'success', message: 'Usuário atualizado com sucesso!' });
            setTimeout(() => setFeedback(null), 3000);
        } else {
            setFeedback({ type: 'error', message: result.message });
        }
        setIsProcessing(false);
    }, 800);
  };

  // Optimized Search Logic using useMemo
  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) return users;

    return users.filter(user =>
      user.nomeCompleto.toLowerCase().includes(term) ||
      user.matricula.includes(term) ||
      user.filial.toLowerCase().includes(term) ||
      user.departamento.toLowerCase().includes(term) ||
      user.setor.toLowerCase().includes(term) ||
      user.login.toLowerCase().includes(term)
    );
  }, [users, searchTerm]);

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out] print:p-0 print:space-y-0">

        {feedback && !isEditModalOpen && !isDeleteModalOpen && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            } print:hidden`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <ShieldAlert className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

        {/* Print Header - Only visible when printing */}
        <div className="hidden print:block mb-8 border-b-2 border-slate-100 pb-6">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Relatório Geral de Usuários</h1>
                    <p className="text-slate-500 text-sm mt-1">K-System Enterprise - Base de Dados Completa</p>
                </div>
                <div className="text-right">
                    <p className="text-xs text-slate-400 uppercase tracking-wider font-semibold">Data de Emissão</p>
                    <p className="text-slate-900 font-mono">{new Date().toLocaleString()}</p>
                </div>
            </div>
            {searchTerm && (
                <div className="mt-4 p-2 bg-slate-50 border border-slate-200 rounded text-sm text-slate-600 inline-block">
                    Filtro aplicado: <span className="font-semibold">"{searchTerm}"</span>
                </div>
            )}
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 min-h-[500px] print:shadow-none print:border-none print:p-0 print:min-h-0">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8 print:hidden">
                <div>
                    <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <Database className="w-6 h-6 text-primary-500"/>
                        Base de Dados de Usuários
                    </h2>
                    <p className="text-slate-500 text-sm mt-1">Gerenciamento completo dos registros do sistema</p>
                </div>

                <div className="flex gap-3 w-full md:w-auto flex-wrap md:flex-nowrap justify-end">
                    <div className="relative flex-1 md:w-80 group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
                        <input
                            type="text"
                            placeholder="Buscar por matrícula, nome, filial, login..."
                            className="w-full pl-10 pr-10 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all text-sm"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            disabled={isLoading}
                        />
                        {searchTerm && (
                            <button 
                                onClick={() => setSearchTerm('')}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 rounded-full hover:bg-slate-200 transition-colors"
                                title="Limpar busca"
                            >
                                <X className="w-3 h-3" />
                            </button>
                        )}
                    </div>

                    <button 
                        type="button"
                        onClick={handlePrint}
                        disabled={isLoading}
                        className="flex items-center gap-2 bg-slate-100 text-slate-700 px-4 py-2.5 rounded-xl hover:bg-slate-200 transition-colors font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        title="Imprimir Lista"
                    >
                        <Printer className="w-4 h-4" />
                        <span className="hidden sm:inline">Imprimir</span>
                    </button>

                    {users.length > 0 && (
                        <button 
                            type="button"
                            onClick={confirmDeleteAll}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-red-50 text-red-600 border border-red-100 px-4 py-2.5 rounded-xl hover:bg-red-100 transition-colors font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Eraser className="w-4 h-4" />
                            Limpar Base
                        </button>
                    )}

                    {onNavigateToRegister && (
                        <button 
                            type="button"
                            onClick={onNavigateToRegister}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2.5 rounded-xl hover:bg-primary-700 transition-colors shadow-lg shadow-primary-500/20 font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Plus className="w-4 h-4" />
                            Novo Usuário
                        </button>
                    )}
                </div>
            </div>

            <div className="overflow-hidden rounded-xl border border-slate-200 shadow-sm print:overflow-visible print:shadow-none print:border-none print:rounded-none">
                <table className="w-full text-left border-collapse">
                    <thead className="print:bg-slate-100">
                        <tr className="bg-slate-50/50 border-b border-slate-200">
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Matrícula</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Nome Completo</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Filial</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Departamento / Setor</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Login</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider text-right print:hidden">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                        {isLoading ? (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                     <div className="flex flex-col items-center justify-center gap-3">
                                        <Spinner size="lg" />
                                        <p className="text-slate-400 font-medium">Carregando registros...</p>
                                     </div>
                                </td>
                            </tr>
                        ) : filteredUsers.length > 0 ? (
                            filteredUsers.map((user) => (
                                <tr key={user.id} className="hover:bg-slate-50/80 transition-colors group print:break-inside-avoid">
                                    <td className="p-4 text-sm text-slate-600 font-mono font-medium print:text-slate-800">{user.matricula}</td>
                                    <td className="p-4">
                                        <div className="font-semibold text-slate-800 text-sm print:text-black">{user.nomeCompleto}</div>
                                        <div className="text-xs text-slate-400">Cadastrado em {new Date(user.dataCadastro).toLocaleDateString()}</div>
                                    </td>
                                    <td className="p-4">
                                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-100 print:bg-transparent print:border-none print:p-0 print:text-slate-800">
                                            {user.filial}
                                        </span>
                                    </td>
                                    <td className="p-4">
                                        <div className="text-sm text-slate-700 print:text-slate-800">{user.departamento}</div>
                                        <div className="text-xs text-slate-500">{user.setor}</div>
                                    </td>
                                    <td className="p-4 text-sm text-slate-600 font-mono bg-slate-50/50 rounded w-fit px-2 print:bg-transparent print:p-0 print:text-slate-800">{user.login}</td>
                                    <td className="p-4 text-right print:hidden">
                                        <div className="flex items-center justify-end gap-2">
                                            <button 
                                                type="button"
                                                onClick={() => handleEditClick(user)} 
                                                className="p-2 text-slate-400 hover:text-primary-600 hover:bg-red-50 rounded-lg transition-all" 
                                                title="Editar"
                                            >
                                                <Edit2 className="w-4 h-4" />
                                            </button>
                                            <button 
                                                type="button"
                                                onClick={(e) => confirmDeleteUser(e, user)} 
                                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all" 
                                                title="Excluir"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                    <div className="flex flex-col items-center justify-center text-slate-400">
                                        <ShieldAlert className="w-12 h-12 mb-3 text-slate-300" />
                                        <p className="text-lg font-medium text-slate-500">
                                            {searchTerm ? `Nenhum resultado para "${searchTerm}"` : 'Nenhum registro encontrado'}
                                        </p>
                                        {searchTerm && (
                                            <button 
                                                onClick={() => setSearchTerm('')}
                                                className="mt-2 text-primary-600 hover:text-primary-700 text-sm font-medium hover:underline print:hidden"
                                            >
                                                Limpar filtros
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <div className="mt-4 flex justify-between items-center text-xs text-slate-400 border-t border-slate-100 pt-4 print:hidden">
                <p>Mostrando {filteredUsers.length} de {users.length} registros</p>
            </div>
             {/* Print Footer */}
             <div className="hidden print:flex mt-4 pt-4 border-t border-slate-200 justify-between text-xs text-slate-500">
                <p>K-System Enterprise - Relatório Administrativo</p>
                <p>Total: {filteredUsers.length}</p>
            </div>
        </div>

        {/* Edit Modal */}
        {isEditModalOpen && editingUser && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s] print:hidden">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="px-6 py-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                        <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                            <Edit2 className="w-5 h-5 text-primary-600"/>
                            Editar Usuário
                        </h3>
                        <button onClick={() => setIsEditModalOpen(false)} disabled={isProcessing} className="text-slate-400 hover:text-slate-600 transition-colors disabled:opacity-50">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <form onSubmit={handleSaveEdit} className="p-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <Input label="Matrícula" name="matricula" value={editingUser.matricula} onChange={handleEditChange} required disabled={isProcessing} />
                            <Select label="Filial" name="filial" value={editingUser.filial} onChange={handleEditChange} options={options.filiais} required disabled={isProcessing} />
                            <div className="col-span-1 md:col-span-2">
                                <Input label="Nome Completo" name="nomeCompleto" value={editingUser.nomeCompleto} onChange={handleEditChange} required disabled={isProcessing} />
                            </div>
                            <Input label="Login" name="login" value={editingUser.login} onChange={handleEditChange} required disabled={isProcessing} />
                            <Input label="Senha" name="senha" type="password" value={editingUser.senha || ''} onChange={handleEditChange} required disabled={isProcessing} />
                            <Select label="Departamento" name="departamento" value={editingUser.departamento} onChange={handleEditChange} options={options.departamentos} required disabled={isProcessing} />
                            <Select label="Setor" name="setor" value={editingUser.setor} onChange={handleEditChange} options={options.setores} required disabled={isProcessing} />
                        </div>
                        <div className="mt-6 flex justify-end gap-3">
                            <button type="button" onClick={() => setIsEditModalOpen(false)} disabled={isProcessing} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors font-medium disabled:opacity-50">Cancelar</button>
                            <button type="submit" disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors font-medium shadow-lg shadow-primary-500/20 disabled:opacity-70 disabled:cursor-not-allowed">
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Save className="w-4 h-4" />}
                                {isProcessing ? 'Salvando...' : 'Salvar Alterações'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* Delete Confirmation Modal */}
        {isDeleteModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s] print:hidden">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertTriangle className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Confirmar Exclusão</h3>
                        <p className="text-slate-500 mb-6">
                            {isDeleteAll 
                                ? "Você está prestes a excluir TODOS os registros da base de dados. Esta ação é irreversível." 
                                : `Tem certeza que deseja excluir o usuário ${userToDelete?.nomeCompleto} (Login: ${userToDelete?.login})?`
                            }
                        </p>

                        <div className="flex gap-3 justify-center">
                            <button 
                                onClick={() => setIsDeleteModalOpen(false)}
                                disabled={isProcessing}
                                className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium disabled:opacity-50"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={handleExecuteDelete}
                                disabled={isProcessing}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors font-medium shadow-lg shadow-red-500/30 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Trash2 className="w-4 h-4" />}
                                {isProcessing ? "Processando..." : (isDeleteAll ? "Sim, Limpar Tudo" : "Sim, Excluir")}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { User } from '../types';
import { Search, Database, ShieldAlert, Plus, X, CheckCircle2, Eraser, AlertTriangle, Printer } from 'lucide-react';
import { Spinner } from './Spinner';

interface UsersListProps {
  onNavigateToRegister?: () => void;
}

export const UsersList: React.FC<UsersListProps> = ({ onNavigateToRegister }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  // Delete Modal State (Only for Delete All now)
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isDeleteAll, setIsDeleteAll] = useState(false);

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = () => {
    setIsLoading(true);
    setTimeout(() => {
        setUsers(dbService.getAllUsers());
        setIsLoading(false);
    }, 600);
  };

  const handlePrint = () => {
      window.print();
  };

  // Trigger Delete All Modal
  const confirmDeleteAll = () => {
    setIsDeleteAll(true);
    setIsDeleteModalOpen(true);
  };

  // Execute Deletion
  const handleExecuteDelete = () => {
    setIsProcessing(true);
    setTimeout(() => {
        if (isDeleteAll) {
            const result = dbService.deleteAllUsers();
            if (result.success) {
                setFeedback({ type: 'success', message: result.message });
                loadUsers();
            } else {
                setFeedback({ type: 'error', message: result.message });
            }
        }

        setIsProcessing(false);
        setIsDeleteModalOpen(false);
        setTimeout(() => setFeedback(null), 3000);
    }, 1000);
  };

  // Optimized Search Logic
  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) return users;

    return users.filter(user =>
      user.nomeCompleto.toLowerCase().includes(term) ||
      user.matricula.includes(term) ||
      user.filial.toLowerCase().includes(term) ||
      user.departamento.toLowerCase().includes(term) ||
      user.setor.toLowerCase().includes(term) ||
      user.login.toLowerCase().includes(term)
    );
  }, [users, searchTerm]);

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out] print:p-0 print:space-y-0">

        {feedback && !isDeleteModalOpen && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            } print:hidden`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <ShieldAlert className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

        {/* Print Header */}
        <div className="hidden print:block mb-8 border-b-2 border-slate-100 pb-6">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Relatório Geral de Usuários</h1>
                    <p className="text-slate-500 text-sm mt-1">K-System Enterprise - Base de Dados Completa</p>
                </div>
                <div className="text-right">
                    <p className="text-xs text-slate-400 uppercase tracking-wider font-semibold">Data de Emissão</p>
                    <p className="text-slate-900 font-mono">{new Date().toLocaleString()}</p>
                </div>
            </div>
            {searchTerm && (
                <div className="mt-4 p-2 bg-slate-50 border border-slate-200 rounded text-sm text-slate-600 inline-block">
                    Filtro aplicado: <span className="font-semibold">"{searchTerm}"</span>
                </div>
            )}
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 min-h-[500px] print:shadow-none print:border-none print:p-0 print:min-h-0">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8 print:hidden">
                <div>
                    <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <Database className="w-6 h-6 text-primary-500"/>
                        Base de Dados de Usuários
                    </h2>
                    <p className="text-slate-500 text-sm mt-1">Gerenciamento completo dos registros do sistema</p>
                </div>

                <div className="flex gap-3 w-full md:w-auto flex-wrap md:flex-nowrap justify-end">
                    <div className="relative flex-1 md:w-80 group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
                        <input
                            type="text"
                            placeholder="Buscar por matrícula, nome, filial, login..."
                            className="w-full pl-10 pr-10 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all text-sm"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            disabled={isLoading}
                        />
                        {searchTerm && (
                            <button 
                                onClick={() => setSearchTerm('')}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 rounded-full hover:bg-slate-200 transition-colors"
                                title="Limpar busca"
                            >
                                <X className="w-3 h-3" />
                            </button>
                        )}
                    </div>

                    <button 
                        type="button"
                        onClick={handlePrint}
                        disabled={isLoading}
                        className="flex items-center gap-2 bg-slate-100 text-slate-700 px-4 py-2.5 rounded-xl hover:bg-slate-200 transition-colors font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        title="Imprimir Lista"
                    >
                        <Printer className="w-4 h-4" />
                        <span className="hidden sm:inline">Imprimir</span>
                    </button>

                    {users.length > 0 && (
                        <button 
                            type="button"
                            onClick={confirmDeleteAll}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-red-50 text-red-600 border border-red-100 px-4 py-2.5 rounded-xl hover:bg-red-100 transition-colors font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Eraser className="w-4 h-4" />
                            Limpar Base
                        </button>
                    )}

                    {onNavigateToRegister && (
                        <button 
                            type="button"
                            onClick={onNavigateToRegister}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2.5 rounded-xl hover:bg-primary-700 transition-colors shadow-lg shadow-primary-500/20 font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Plus className="w-4 h-4" />
                            Novo Usuário
                        </button>
                    )}
                </div>
            </div>

            <div className="overflow-hidden rounded-xl border border-slate-200 shadow-sm print:overflow-visible print:shadow-none print:border-none print:rounded-none">
                <table className="w-full text-left border-collapse">
                    <thead className="print:bg-slate-100">
                        <tr className="bg-slate-50/50 border-b border-slate-200">
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Matrícula</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Nome Completo</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Filial</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Departamento / Setor</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Login</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                        {isLoading ? (
                            <tr>
                                <td colSpan={5} className="p-12 text-center">
                                     <div className="flex flex-col items-center justify-center gap-3">
                                        <Spinner size="lg" />
                                        <p className="text-slate-400 font-medium">Carregando registros...</p>
                                     </div>
                                </td>
                            </tr>
                        ) : filteredUsers.length > 0 ? (
                            filteredUsers.map((user) => (
                                <tr key={user.id} className="hover:bg-slate-50/80 transition-colors group print:break-inside-avoid">
                                    <td className="p-4 text-sm text-slate-600 font-mono font-medium print:text-slate-800">{user.matricula}</td>
                                    <td className="p-4">
                                        <div className="font-semibold text-slate-800 text-sm print:text-black">{user.nomeCompleto}</div>
                                        <div className="text-xs text-slate-400">Cadastrado em {new Date(user.dataCadastro).toLocaleDateString()}</div>
                                    </td>
                                    <td className="p-4">
                                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-100 print:bg-transparent print:border-none print:p-0 print:text-slate-800">
                                            {user.filial}
                                        </span>
                                    </td>
                                    <td className="p-4">
                                        <div className="text-sm text-slate-700 print:text-slate-800">{user.departamento}</div>
                                        <div className="text-xs text-slate-500">{user.setor}</div>
                                    </td>
                                    <td className="p-4 text-sm text-slate-600 font-mono bg-slate-50/50 rounded w-fit px-2 print:bg-transparent print:p-0 print:text-slate-800">{user.login}</td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={5} className="p-12 text-center">
                                    <div className="flex flex-col items-center justify-center text-slate-400">
                                        <ShieldAlert className="w-12 h-12 mb-3 text-slate-300" />
                                        <p className="text-lg font-medium text-slate-500">
                                            {searchTerm ? `Nenhum resultado para "${searchTerm}"` : 'Nenhum registro encontrado'}
                                        </p>
                                        {searchTerm && (
                                            <button 
                                                onClick={() => setSearchTerm('')}
                                                className="mt-2 text-primary-600 hover:text-primary-700 text-sm font-medium hover:underline print:hidden"
                                            >
                                                Limpar filtros
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <div className="mt-4 flex justify-between items-center text-xs text-slate-400 border-t border-slate-100 pt-4 print:hidden">
                <p>Mostrando {filteredUsers.length} de {users.length} registros</p>
            </div>
             {/* Print Footer */}
             <div className="hidden print:flex mt-4 pt-4 border-t border-slate-200 justify-between text-xs text-slate-500">
                <p>K-System Enterprise - Relatório Administrativo</p>
                <p>Total: {filteredUsers.length}</p>
            </div>
        </div>

        {/* Delete Confirmation Modal (Only for Delete All) */}
        {isDeleteModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s] print:hidden">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertTriangle className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Confirmar Exclusão</h3>
                        <p className="text-slate-500 mb-6">
                            Você está prestes a excluir TODOS os registros da base de dados. Esta ação é irreversível.
                        </p>

                        <div className="flex gap-3 justify-center">
                            <button 
                                onClick={() => setIsDeleteModalOpen(false)}
                                disabled={isProcessing}
                                className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium disabled:opacity-50"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={handleExecuteDelete}
                                disabled={isProcessing}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors font-medium shadow-lg shadow-red-500/30 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Eraser className="w-4 h-4" />}
                                {isProcessing ? "Processando..." : "Sim, Limpar Tudo"}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState } from 'react';
import { dbService } from '../services/dbService';
import { SystemUser } from '../types';
import { User, Lock } from 'lucide-react';
import { Spinner } from './Spinner';

interface LoginProps {
  onLoginSuccess: (user: SystemUser) => void;
}

export const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [login, setLogin] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Simulate network delay for realism
    setTimeout(() => {
      // Use the new Authentication method against System Users DB
      const user = dbService.authenticateSystemUser(login, password);

      if (user) {
        onLoginSuccess(user);
      } else {
        setError('Acesso negado. Verifique suas credenciais.');
        setLoading(false);
      }
    }, 1200);
  };

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-slate-100 p-4 font-sans">

      {/* Main Container Card */}
      <div className="relative bg-white rounded-[20px] shadow-[0_15px_40px_rgba(0,0,0,0.15)] overflow-hidden w-full max-w-[900px] h-auto min-h-[550px] flex flex-col md:flex-row">

        {/* Left Panel (Colored) */}
        <div className="w-full md:w-2/5 bg-gradient-to-br from-primary-600 to-primary-800 text-white flex flex-col items-center justify-center p-8 text-center relative overflow-hidden">
            {/* Decorative circles in background */}
            <div className="absolute top-[-50px] left-[-50px] w-32 h-32 rounded-full bg-white/10 blur-xl"></div>
            <div className="absolute bottom-[-20px] right-[-20px] w-40 h-40 rounded-full bg-white/10 blur-xl"></div>

            <div className="mt-4">
                <button className="border-2 border-white text-white rounded-full px-10 py-2.5 font-semibold text-xs tracking-wider uppercase hover:bg-white hover:text-primary-600 transition-all duration-300 cursor-default">
                   K-SYSTEM
                </button>
            </div>
        </div>

        {/* Right Panel (White) - Form */}
        <div className="w-full md:w-3/5 bg-white flex flex-col items-center justify-center p-8 md:p-12">

            <div className="w-full max-w-xs">
                <h1 className="text-3xl font-bold text-primary-600 mb-2 tracking-tight text-center">Acesse o Sistema</h1>
                <p className="text-slate-400 text-sm mb-8 text-center">Insira suas credenciais para continuar</p>

                <form onSubmit={handleSubmit} className="flex flex-col gap-5">

                    {/* Input User */}
                    <div className="relative group">
                        <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors">
                            <User className="w-5 h-5" />
                        </div>
                        <input 
                            type="text" 
                            placeholder="Usuário"
                            value={login}
                            onChange={(e) => setLogin(e.target.value.toUpperCase())}
                            required
                            disabled={loading}
                            className="w-full bg-white border border-slate-300 rounded-lg px-4 py-3 pl-12 text-sm text-slate-700 placeholder-slate-400 outline-none focus:ring-2 focus:ring-primary-100 focus:border-primary-500 transition-all shadow-sm disabled:bg-slate-50"
                        />
                    </div>

                    {/* Input Password */}
                    <div className="relative group">
                        <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors">
                            <Lock className="w-5 h-5" />
                        </div>
                        <input 
                            type="password" 
                            placeholder="Senha" 
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                            disabled={loading}
                            className="w-full bg-white border border-slate-300 rounded-lg px-4 py-3 pl-12 text-sm text-slate-700 placeholder-slate-400 outline-none focus:ring-2 focus:ring-primary-100 focus:border-primary-500 transition-all shadow-sm disabled:bg-slate-50"
                        />
                    </div>

                    {error && (
                        <div className="text-xs text-red-500 bg-red-50 p-3 rounded-lg text-center border border-red-100 animate-[shake_0.5s_ease-in-out]">
                            {error}
                        </div>
                    )}

                    <button 
                        type="submit" 
                        disabled={loading}
                        className="mt-2 bg-primary-600 text-white rounded-full px-12 py-3.5 font-bold text-xs uppercase tracking-wider hover:bg-primary-700 hover:shadow-lg hover:shadow-primary-500/30 transform active:scale-[0.98] transition-all disabled:opacity-70 disabled:cursor-not-allowed block w-full flex justify-center items-center gap-2"
                    >
                        {loading ? (
                            <>
                                <Spinner size="sm" variant="white" />
                                <span>AUTENTICANDO...</span>
                            </>
                        ) : 'ENTRAR'}
                    </button>

                </form>
            </div>

        </div>

      </div>

      {/* Footer Copy */}
      <div className="absolute bottom-4 text-slate-400 text-xs">
         © {new Date().getFullYear()} K-System Enterprise
      </div>
    </div>
  );
};

import React from 'react';

interface LogoProps {
  className?: string;
  variant?: 'white' | 'primary';
}

export const Logo: React.FC<LogoProps> = ({ className = "w-10 h-10", variant = 'primary' }) => {
  const color = variant === 'white' ? '#ffffff' : '#dc2626';
  const fill = variant === 'white' ? '#ffffff' : '#dc2626';

  return (
    <svg 
      viewBox="0 0 100 100" 
      className={className} 
      fill="none" 
      xmlns="http://www.w3.org/2000/svg"
    >
      {/* Hexagon Background */}
      <path 
        d="M50 10L85 30V70L50 90L15 70V30L50 10Z" 
        fill={fill} 
        fillOpacity="0.1" 
        stroke={color} 
        strokeWidth="3"
        strokeOpacity="0.5"
      />

      {/* "K" Letter Shape */}
      <path 
        d="M35 30V70" 
        stroke={color} 
        strokeWidth="8" 
        strokeLinecap="round" 
      />
      <path 
        d="M65 30L35 50L65 70" 
        stroke={color} 
        strokeWidth="8" 
        strokeLinecap="round" 
        strokeLinejoin="round" 
      />

      {/* Optional decorative dot */}
      <circle cx="50" cy="50" r="3" fill={color} />
    </svg>
  );
};

