    } else if (selectedFilial) {
      const filtered = allUsers.filter(u => u.filial === selectedFilial);
      setUsers(filtered);
    } else {
      setUsers([]);
    }
  }, [selectedFilial, allUsers]);

  const handlePrint = () => {
    // Delay to ensure rendering is complete before browser print dialog
    setTimeout(() => {
        window.print();
    }, 100);
  };

  const handleExportPDF = () => {
    setIsExporting(true);

