                            <p className="text-xs text-gray-500 uppercase font-bold">Filtro Aplicado</p>
                            <p className="text-sm font-bold text-black">{selectedFilial === 'TODAS' ? 'TODAS AS FILIAIS' : selectedFilial}</p>
