                        </tbody>
                    </table>
                </div>
            ) : (
                <div className="text-center py-12 bg-slate-50 rounded-xl border border-dashed border-slate-300 print:bg-white print:border-black">
                    <Users className="w-12 h-12 text-slate-300 mx-auto mb-3 print:hidden" />
