                    {/* Footer */}
                    <div className="flex mt-8 pt-4 border-t border-black text-xs text-gray-500 justify-between items-center absolute bottom-[15mm] left-[15mm] right-[15mm]">
                        <p>Relatório gerado automaticamente pelo sistema.</p>
                        <p>Página 1 de 1</p>
                    </div>

                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

