                                disabled={userRole !== 'ADMIN'}
                            />

                            <Select 
                                label="Departamento" 
                                options={options.departamentos}
                                value={editForm.departamento}
                                onChange={e => setEditForm({...editForm, departamento: e.target.value})}
                                required
                                disabled={userRole !== 'ADMIN'}
