import React, { useState, useEffect } from 'react';
import { dbService } from '../services/dbService';
import { Input } from './Input';
import { Select } from './Select';
import { Save, AlertCircle, CheckCircle2, ShieldAlert } from 'lucide-react';
import { Spinner } from './Spinner';

interface RegisterUserProps {
  userRole?: 'ADMIN' | 'OPERADOR';
}

export const RegisterUser: React.FC<RegisterUserProps> = ({ userRole = 'OPERADOR' }) => {
  const [formData, setFormData] = useState({
    matricula: '',
    nomeCompleto: '',
    filial: '',
    login: '',
    senha: '',
    departamento: '',
    setor: ''
  });

  const [isSaving, setIsSaving] = useState(false);

  // Dynamic Options States
  const [options, setOptions] = useState({
      filiais: [] as string[],
      departamentos: [] as string[],
      setores: [] as string[]
  });

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [fieldErrors, setFieldErrors] = useState<{ login?: string }>({});

  useEffect(() => {
    // Load dynamic options from DB
    setOptions({
        filiais: dbService.getFiliais(),
        departamentos: dbService.getDepartamentos(),
        setores: dbService.getSetores()
    });
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    // Apply Uppercase constraints immediately
    let finalValue = value;
    if (['nomeCompleto', 'login'].includes(name)) {
        finalValue = value.toUpperCase();
    }

    setFormData(prev => ({ ...prev, [name]: finalValue }));

    // Clear field specific error when user starts typing again
    if (name === 'login') {
        setFieldErrors(prev => ({ ...prev, login: undefined }));
    }

    if (feedback) setFeedback(null);
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      const { name, value } = e.target;
      if (name === 'login' && value) {
          const exists = dbService.checkLoginExists(value);
          if (exists) {
              setFieldErrors(prev => ({ ...prev, login: `O login ${value} já está em uso.` }));
          }
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (Object.values(formData).some(x => x === '')) {
        setFeedback({ type: 'error', message: 'Por favor, preencha todos os campos.' });
        return;
    }

    if (fieldErrors.login) {
        setFeedback({ type: 'error', message: 'Corrija os erros do formulário antes de salvar.' });
        return;
    }

    setIsSaving(true);
    // Simulate API delay
    setTimeout(() => {
        const result = dbService.addUser({
            ...formData
        });

        if (result.success) {
            setFeedback({ type: 'success', message: result.message });
            setFormData({
                matricula: '',
                nomeCompleto: '',
                filial: '',
                login: '',
                senha: '',
                departamento: '',
                setor: ''
            });
        } else {
            setFeedback({ type: 'error', message: result.message });
        }
        setIsSaving(false);
    }, 1000);
  };

  if (userRole !== 'ADMIN') {
      return (
          <div className="flex h-full items-center justify-center p-6 animate-[fadeIn_0.3s]">
              <div className="bg-white p-8 rounded-2xl shadow-xl text-center max-w-md">
                  <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                      <ShieldAlert className="w-8 h-8 text-red-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800 mb-2">Acesso Restrito</h2>
                  <p className="text-slate-500">
                      Seu nível de acesso (OPERADOR) não permite realizar novos cadastros. Solicite permissão ao administrador.
                  </p>
              </div>
          </div>
      );
  }

  return (
    <div className="max-w-4xl mx-auto p-6 animate-[fadeIn_0.3s_ease-out]">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
        <div className="bg-primary-900 p-6 flex items-center justify-between">
            <div>
                <h2 className="text-2xl font-bold text-white">Novo Colaborador</h2>
                <p className="text-primary-100 text-sm mt-1">Preencha os dados abaixo para cadastrar um novo usuário no sistema.</p>
            </div>
            <div className="hidden sm:block text-right">
                <p className="text-primary-200 text-xs uppercase tracking-wider">Data do Cadastro</p>
                <p className="text-white font-mono">{new Date().toLocaleDateString()}</p>
            </div>
        </div>

        <form onSubmit={handleSubmit} className="p-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

                {/* ID and Branch Row */}
                <div className="col-span-1">
                    <Input 
                        label="Matrícula"
                        name="matricula"
                        type="number"
                        placeholder="Ex: 1005"
                        value={formData.matricula}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                     <Select
                        label="Filial"
                        name="filial"
                        value={formData.filial}
                        onChange={handleChange}
                        options={options.filiais}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Name Row */}
                <div className="col-span-1 md:col-span-2">
                    <Input 
                        label="Nome Completo (Automático Caixa Alta)"
                        name="nomeCompleto"
                        type="text"
                        placeholder="NOME DO FUNCIONÁRIO"
                        value={formData.nomeCompleto}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Login Info */}
                <div className="col-span-1">
                    <Input 
                        label="Login (Automático Caixa Alta)"
                        name="login"
                        type="text"
                        placeholder="USUARIO.LOGIN"
                        value={formData.login}
                        onChange={handleChange}
                        onBlur={handleBlur}
                        error={fieldErrors.login}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                    <Input 
                        label="Senha"
                        name="senha"
                        type="password"
                        placeholder="••••••••"
                        value={formData.senha}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Job Info */}
                <div className="col-span-1">
                    <Select
                        label="Departamento"
                        name="departamento"
                        value={formData.departamento}
                        onChange={handleChange}
                        options={options.departamentos}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                     <Select
                        label="Setor"
                        name="setor"
                        value={formData.setor}
                        onChange={handleChange}
                        options={options.setores}
                        required
                        disabled={isSaving}
                    />
                </div>
            </div>

            {/* Feedback Message */}
            {feedback && (
                <div className={`mt-6 p-4 rounded-lg flex items-center gap-3 ${feedback.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                    {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                    <span className="font-medium">{feedback.message}</span>
                </div>
            )}

            <div className="mt-8 flex justify-end">
                <button 
                    type="submit"
                    disabled={isSaving}
                    className="flex items-center gap-2 bg-primary-600 text-white px-8 py-3 rounded-xl hover:bg-primary-700 active:scale-95 transition-all shadow-lg shadow-primary-500/30 font-semibold disabled:opacity-70 disabled:cursor-not-allowed"
                >
                    {isSaving ? <Spinner size="sm" variant="white" /> : <Save className="w-5 h-5" />}
                    {isSaving ? 'Salvando...' : 'Salvar Cadastro'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/dbService';
import { Plus, Trash2, List, Save, Building, Briefcase, Layers, CheckCircle2, AlertCircle, X, AlertTriangle } from 'lucide-react';
import { Input } from './Input';
import { Spinner } from './Spinner';

interface ResourceRegisterProps {
  type: 'FILIAL' | 'DEPARTAMENTO' | 'SETOR';
  userRole: 'ADMIN' | 'OPERADOR';
}

export const ResourceRegister: React.FC<ResourceRegisterProps> = ({ type, userRole }) => {
  const [items, setItems] = useState<string[]>([]);
  const [newItem, setNewItem] = useState('');
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  // Delete Modal State
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const config = {
    FILIAL: {
      title: 'Gerenciar Filiais',
      label: 'Nova Filial',
      icon: Building,
      description: 'Cadastre as unidades físicas da empresa.',
      get: dbService.getFiliais,
      add: dbService.addFilial,
      remove: dbService.deleteFilial
    },
    DEPARTAMENTO: {
      title: 'Gerenciar Departamentos',
      label: 'Novo Departamento',
      icon: Layers,
      description: 'Estruture as grandes áreas da organização.',
      get: dbService.getDepartamentos,
      add: dbService.addDepartamento,
      remove: dbService.deleteDepartamento
    },
    SETOR: {
      title: 'Gerenciar Setores',
      label: 'Novo Setor',
      icon: Briefcase,
      description: 'Defina as divisões de trabalho dentro dos departamentos.',
      get: dbService.getSetores,
      add: dbService.addSetor,
      remove: dbService.deleteSetor
    }
  }[type];

  useEffect(() => {
    loadItems();
    setFeedback(null);
    setNewItem('');
    setIsDeleteModalOpen(false);
    setItemToDelete(null);
  }, [type]);

  const loadItems = () => {
    setItems(config.get());
  };

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItem.trim()) return;

    const success = config.add(newItem);
    if (success) {
      setNewItem('');
      loadItems();
      setFeedback({ type: 'success', message: 'Item cadastrado com sucesso!' });
      setTimeout(() => setFeedback(null), 3000);
    } else {
      setFeedback({ type: 'error', message: 'Este item já existe na lista.' });
    }
  };

  // Open the custom delete modal
  const requestDelete = (e: React.MouseEvent, item: string) => {
    e.stopPropagation();
    e.preventDefault();
    setItemToDelete(item);
    setIsDeleteModalOpen(true);
  };

  // Execute the deletion
  const confirmDelete = () => {
    if (!itemToDelete) return;

    setIsProcessing(true);

    // Simulate a small delay for better UX
    setTimeout(() => {
        const success = config.remove(itemToDelete);

        if (success) {
            loadItems();
            setFeedback({ type: 'success', message: 'Item removido com sucesso.' });
        } else {
            setFeedback({ type: 'error', message: 'Erro ao remover item. Tente recarregar a página.' });
        }

        setIsProcessing(false);
        setIsDeleteModalOpen(false);
        setItemToDelete(null);

        setTimeout(() => setFeedback(null), 3000);
    }, 500);
  };

  const Icon = config.icon;

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">
        {/* Feedback Toast */}
        {feedback && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            }`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <AlertCircle className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">

        {/* Header */}
        <div className="bg-primary-900 p-6 flex items-center gap-4">
          <div className="p-3 bg-primary-800 rounded-lg">
             <Icon className="w-6 h-6 text-white" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-white">{config.title}</h2>
            <p className="text-primary-200 text-sm">
                {userRole === 'ADMIN' ? config.description : 'Visualização de registros do sistema.'}
            </p>
          </div>
        </div>

        <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-12">

          {/* Left: Add Form - ONLY FOR ADMIN */}
          {userRole === 'ADMIN' && (
            <div className="space-y-6">
               <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-2">
                  <Plus className="w-5 h-5 text-primary-500" />
                  Cadastrar Novo
               </h3>

               <form onSubmit={handleAdd} className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                  <Input 
                     label={`Nome do ${type === 'FILIAL' ? 'Filial' : type === 'SETOR' ? 'Setor' : 'Departamento'}`}
                     value={newItem}
                     onChange={(e) => setNewItem(e.target.value.toUpperCase())}
                     placeholder="Digite o nome..."
                     fullWidth
                  />
                  <button 
                    type="submit"
                    disabled={!newItem.trim()}
                    className="w-full mt-2 flex items-center justify-center gap-2 bg-primary-600 text-white py-3 rounded-lg hover:bg-primary-700 transition-all font-semibold disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-primary-500/20"
                  >
                    <Save className="w-4 h-4" />
                    Salvar Cadastro
                  </button>
               </form>
            </div>
          )}

          {/* Right: List - Full Width if Operator */}
          <div className={`space-y-4 ${userRole !== 'ADMIN' ? 'col-span-1 md:col-span-2' : ''}`}>
             <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-2">
                <List className="w-5 h-5 text-slate-500" />
                Registros Atuais ({items.length})
             </h3>

             <div className="max-h-[400px] overflow-y-auto pr-2 space-y-2 custom-scrollbar">
                {items.length > 0 ? items.map((item) => (
                   <div key={item} className="flex justify-between items-center p-3 bg-white border border-slate-200 rounded-lg hover:border-primary-300 hover:shadow-sm transition-all group">
                      <span className="font-medium text-slate-700 pl-2">{item}</span>

                      {/* Delete Button - ONLY FOR ADMIN */}
                      {userRole === 'ADMIN' && (
                          <button 
                            type="button"
                            onClick={(e) => requestDelete(e, item)}
                            className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-100 transition-colors"
                            title="Excluir"
                          >
                             <Trash2 className="w-4 h-4" />
                          </button>
                      )}
                   </div>
                )) : (
                  <div className="text-center py-8 text-slate-400">
                    Nenhum registro encontrado.
                  </div>
                )}
             </div>
          </div>

        </div>
      </div>

       {/* Delete Confirmation Modal */}
       {isDeleteModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s]">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertTriangle className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Confirmar Exclusão</h3>
                        <p className="text-slate-500 mb-6">
                            Tem certeza que deseja excluir o item <strong>"{itemToDelete}"</strong>?
                            <br/>
                            <span className="text-xs text-slate-400 mt-1 block">Esta ação não pode ser desfeita.</span>
                        </p>

                        <div className="flex gap-3 justify-center">
                            <button 
                                onClick={() => setIsDeleteModalOpen(false)}
                                disabled={isProcessing}
                                className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium disabled:opacity-50"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={confirmDelete}
                                disabled={isProcessing}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors font-medium shadow-lg shadow-red-500/30 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Trash2 className="w-4 h-4" />}
                                {isProcessing ? "Excluindo..." : "Sim, Excluir"}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/dbService';
import { SystemUser } from '../types';
import { ShieldCheck, UserPlus, Trash2, Key, Save, AlertCircle, CheckCircle2, X, AlertTriangle } from 'lucide-react';
import { Input } from './Input';
import { Select } from './Select';

interface SystemUsersManagementProps {
  userRole: 'ADMIN' | 'OPERADOR';
}

export const SystemUsersManagement: React.FC<SystemUsersManagementProps> = ({ userRole }) => {
  const [users, setUsers] = useState<SystemUser[]>([]);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const [newUser, setNewUser] = useState({
      nome: '',
      login: '',
      senha: '',
      role: 'ADMIN' as 'ADMIN' | 'OPERADOR'
  });

  // Delete Modal State
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [userToDelete, setUserToDelete] = useState<SystemUser | null>(null);

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = () => {
    setUsers(dbService.getSystemUsers());
  };

  const handleAddUser = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newUser.nome || !newUser.login || !newUser.senha) {
          setFeedback({ type: 'error', message: 'Preencha todos os campos obrigatórios.' });
          return;
      }

      const result = dbService.addSystemUser({
          nome: newUser.nome.toUpperCase(),
          login: newUser.login.toUpperCase(),
          senha: newUser.senha,
          role: newUser.role
      });

      if (result.success) {
          setFeedback({ type: 'success', message: result.message });
          setNewUser({ nome: '', login: '', senha: '', role: 'ADMIN' });
          loadUsers();
          setTimeout(() => setFeedback(null), 3000);
      } else {
          setFeedback({ type: 'error', message: result.message });
      }
  };

  const confirmDelete = (e: React.MouseEvent, user: SystemUser) => {
      e.preventDefault();
      e.stopPropagation();
      setUserToDelete(user);
      setIsDeleteModalOpen(true);
  };

  const handleExecuteDelete = () => {
      if (!userToDelete) return;

      const result = dbService.deleteSystemUser(userToDelete.id);
      if (result.success) {
          loadUsers();
          setFeedback({ type: 'success', message: result.message });
      } else {
          setFeedback({ type: 'error', message: result.message });
      }

      setIsDeleteModalOpen(false);
      setUserToDelete(null);
      setTimeout(() => setFeedback(null), 3000);
  };

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">

        {feedback && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            }`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <AlertCircle className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="bg-primary-900 p-6 flex items-center gap-4">
          <div className="p-3 bg-white/20 rounded-lg">
             <ShieldCheck className="w-6 h-6 text-white" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-white">Controle de Acesso</h2>
            <p className="text-primary-200 text-sm">
                {userRole === 'ADMIN' ? 'Gerencie os usuários que podem fazer login no sistema.' : 'Visualização de usuários com acesso ao sistema.'}
            </p>
          </div>
        </div>

        <div className="p-8 grid grid-cols-1 lg:grid-cols-3 gap-12">

            {/* Formulario - ONLY ADMIN */}
            {userRole === 'ADMIN' && (
                <div className="lg:col-span-1 space-y-6">
                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-2">
                        <UserPlus className="w-5 h-5 text-primary-500" />
                        Novo Usuário de Sistema
                    </h3>

                    <form onSubmit={handleAddUser} className="bg-slate-50 p-6 rounded-xl border border-slate-200 space-y-4">
                        <Input 
                            label="Nome do Usuário"
                            value={newUser.nome}
                            onChange={e => setNewUser({...newUser, nome: e.target.value.toUpperCase()})}
                            placeholder="Ex: JOÃO SILVA"
                            required
                        />
                        <Input 
                            label="Login de Acesso"
                            value={newUser.login}
                            onChange={e => setNewUser({...newUser, login: e.target.value.toUpperCase()})}
                            placeholder="Ex: ADMIN"
                            required
                        />
                        <Input 
                            label="Senha"
                            type="password"
                            value={newUser.senha}
                            onChange={e => setNewUser({...newUser, senha: e.target.value})}
                            placeholder="••••••"
                            required
                        />
                        <Select 
                            label="Nível de Permissão"
                            value={newUser.role}
                            onChange={e => setNewUser({...newUser, role: e.target.value as any})}
                            options={['ADMIN', 'OPERADOR']}
                        />

                        <button 
                            type="submit"
                            className="w-full flex items-center justify-center gap-2 bg-primary-600 text-white py-3 rounded-lg hover:bg-primary-700 transition-all font-semibold shadow-lg shadow-primary-500/20 mt-4"
                        >
                            <Save className="w-4 h-4" />
                            Criar Acesso
                        </button>
                    </form>
                </div>
            )}

            {/* Lista - Full width if Operator */}
            <div className={`space-y-4 ${userRole !== 'ADMIN' ? 'lg:col-span-3' : 'lg:col-span-2'}`}>
                 <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-2">
                    <Key className="w-5 h-5 text-slate-500" />
                    Usuários com Acesso ({users.length})
                </h3>

                <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="p-4 text-xs font-semibold text-slate-500 uppercase">Usuário</th>
                                <th className="p-4 text-xs font-semibold text-slate-500 uppercase">Login</th>
                                <th className="p-4 text-xs font-semibold text-slate-500 uppercase">Permissão</th>
                                {userRole === 'ADMIN' && <th className="p-4 text-xs font-semibold text-slate-500 uppercase text-right">Ações</th>}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {users.map(user => (
                                <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                                    <td className="p-4">
                                        <div className="font-bold text-slate-700">{user.nome}</div>
                                        <div className="text-xs text-slate-400">Criado em: {new Date(user.createdAt).toLocaleDateString()}</div>
                                    </td>
                                    <td className="p-4 text-sm font-mono text-slate-600 bg-slate-50 w-fit rounded">{user.login}</td>
                                    <td className="p-4">
                                        <span className={`px-2 py-1 rounded text-xs font-bold ${user.role === 'ADMIN' ? 'bg-primary-100 text-primary-700' : 'bg-slate-100 text-slate-700'}`}>
                                            {user.role}
                                        </span>
                                    </td>
                                    {userRole === 'ADMIN' && (
                                        <td className="p-4 text-right">
                                            <button 
                                                onClick={(e) => confirmDelete(e, user)}
                                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                                                title="Revogar Acesso"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </td>
                                    )}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

        </div>
      </div>

       {/* Delete Confirmation Modal */}
        {isDeleteModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s]">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertTriangle className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Confirmar Revogação</h3>
                        <p className="text-slate-500 mb-6">
                            Tem certeza que deseja revogar o acesso do usuário <strong>{userToDelete?.nome}</strong> (Login: {userToDelete?.login})?
                        </p>

                        <div className="flex gap-3 justify-center">
                            <button 
                                onClick={() => setIsDeleteModalOpen(false)}
                                className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={handleExecuteDelete}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors font-medium shadow-lg shadow-red-500/30 flex items-center gap-2"
                            >
                                <Trash2 className="w-4 h-4" />
                                Sim, Revogar
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Input } from './Input';
import { Select } from './Select';
import { Database, Server, Save, Activity, CheckCircle2, XCircle, Lock } from 'lucide-react';
import { Spinner } from './Spinner';

interface DatabaseSettingsProps {
    userRole: 'ADMIN' | 'OPERADOR';
}

export const DatabaseSettings: React.FC<DatabaseSettingsProps> = ({ userRole }) => {
  const [config, setConfig] = useState({
    type: '',
    host: '',
    port: '',
    database: '',
    user: '',
    password: ''
  });

  const [status, setStatus] = useState<'DISCONNECTED' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');
  const [lastCheck, setLastCheck] = useState<string | null>(null);

  // Load saved config on mount
  useEffect(() => {
    const saved = localStorage.getItem('k_system_db_config');
    if (saved) {
      setConfig(JSON.parse(saved));
      // Optionally simulate that we are already connected if config exists
      setStatus('CONNECTED');
      setLastCheck(new Date().toLocaleTimeString());
    }
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setConfig({ ...config, [e.target.name]: e.target.value });
    if (status === 'CONNECTED' || status === 'ERROR') {
        setStatus('DISCONNECTED'); // Reset status on change
    }
  };

  const handleTestConnection = (e: React.FormEvent) => {
    e.preventDefault();

    if (userRole !== 'ADMIN') return;

    if (!config.type || !config.host || !config.user) {
        setStatus('ERROR');
        return;
    }

    setStatus('CONNECTING');

    // Simulate network request
    setTimeout(() => {
        // Simple mock validation logic
        if (config.host.includes('.') || config.host === 'localhost') {
            setStatus('CONNECTED');
            setLastCheck(new Date().toLocaleTimeString());
            localStorage.setItem('k_system_db_config', JSON.stringify(config));
        } else {
            setStatus('ERROR');
        }
    }, 2000);
  };

  const isDisabled = userRole !== 'ADMIN';

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="bg-primary-900 p-6 flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        <Server className="w-6 h-6 text-primary-200"/>
                        Configuração de Conexão
                    </h2>
                    <p className="text-primary-200 text-sm mt-1">Gerencie a conexão com o banco de dados externo.</p>
                </div>
                <div className="hidden sm:flex items-center gap-3 bg-primary-800 px-4 py-2 rounded-lg border border-primary-700">
                    <div className="text-right">
                        <p className="text-xs text-primary-200 uppercase tracking-wider font-semibold">Status Atual</p>
                        <p className={`text-sm font-bold flex items-center justify-end gap-1.5 ${
                            status === 'CONNECTED' ? 'text-green-400' : 
                            status === 'CONNECTING' ? 'text-yellow-400' : 
                            status === 'ERROR' ? 'text-red-300' : 'text-slate-300'
                        }`}>
                            {status === 'CONNECTED' && <CheckCircle2 className="w-4 h-4" />}
                            {status === 'ERROR' && <XCircle className="w-4 h-4" />}
                            {status === 'CONNECTING' && <Spinner size="sm" variant="white" />}
                            {status === 'DISCONNECTED' && <Activity className="w-4 h-4" />}
                            {status === 'CONNECTED' ? 'CONECTADO' : 
                             status === 'CONNECTING' ? 'CONECTANDO...' : 
                             status === 'ERROR' ? 'FALHA NA CONEXÃO' : 'DESCONECTADO'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="p-8">
                {isDisabled && (
                    <div className="mb-6 p-4 bg-yellow-50 border border-yellow-100 rounded-lg flex items-center gap-3 text-yellow-800 text-sm">
                        <Lock className="w-5 h-5" />
                        <span>Modo de Leitura: Apenas administradores podem alterar as configurações de conexão.</span>
                    </div>
                )}

                <form onSubmit={handleTestConnection}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                        <div className="col-span-1 md:col-span-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Parâmetros do Servidor
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Select 
                                label="Tipo de Banco de Dados"
                                name="type"
                                options={['MySQL', 'PostgreSQL', 'Oracle', 'SQL Server', 'MariaDB']}
                                value={config.type}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Nome da Base (Database)"
                                name="database"
                                placeholder="ex: k_system_prod"
                                value={config.database}
                                onChange={handleChange}
                                disabled={isDisabled}
                            />
                        </div>

                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Host / IP"
                                name="host"
                                placeholder="ex: 192.168.1.50"
                                value={config.host}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Porta"
                                name="port"
                                placeholder="ex: 3306"
                                value={config.port}
                                onChange={handleChange}
                                type="number"
                                disabled={isDisabled}
                            />
                        </div>

                        <div className="col-span-1 md:col-span-2 mt-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Credenciais de Acesso
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Input 
                                label="Usuário"
                                name="user"
                                placeholder="root"
                                value={config.user}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Senha"
                                name="password"
                                type="password"
                                placeholder="••••••••"
                                value={config.password}
                                onChange={handleChange}
                                disabled={isDisabled}
                            />
                        </div>
                    </div>

                    <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                        <div className="text-xs text-slate-400">
                            {lastCheck && <span>Última verificação: {lastCheck}</span>}
                        </div>
                        {userRole === 'ADMIN' && (
                            <div className="flex gap-3">
                                <button
                                    type="button" 
                                    onClick={() => {
                                        setConfig({ type: '', host: '', port: '', database: '', user: '', password: '' });
                                        setStatus('DISCONNECTED');
                                        localStorage.removeItem('k_system_db_config');
                                    }}
                                    className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-xl transition-colors"
                                >
                                    Limpar
                                </button>
                                <button 
                                    type="submit"
                                    disabled={status === 'CONNECTING'}
                                    className={`
                                        flex items-center gap-2 px-8 py-2.5 bg-primary-600 text-white rounded-xl font-semibold shadow-lg shadow-primary-500/30 hover:bg-primary-700 transition-all active:scale-95
                                        ${status === 'CONNECTING' ? 'opacity-70 cursor-not-allowed' : ''}
                                    `}
                                >
                                    {status === 'CONNECTING' ? (
                                        <>
                                            <Spinner size="sm" variant="white" />
                                            <span>Verificando...</span>
                                        </>
                                    ) : (
                                        <>
                                            <Save className="w-5 h-5" />
                                            Salvar e Conectar
                                        </>
                                    )}
                                </button>
                            </div>
                        )}
                    </div>
                </form>
            </div>
        </div>

        {/* Info Card */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-red-50 border border-red-100 p-6 rounded-xl flex items-start gap-4">
                <Database className="w-8 h-8 text-red-500 shrink-0" />
                <div>
                    <h4 className="font-bold text-red-900 mb-1">Modo Híbrido</h4>
                    <p className="text-sm text-red-700 leading-relaxed">
                        O sistema operará em modo offline (Local Storage) caso a conexão com o servidor falhe.
                    </p>
                </div>
            </div>
            <div className="bg-slate-50 border border-slate-200 p-6 rounded-xl flex items-start gap-4 md:col-span-2">
                <Server className="w-8 h-8 text-slate-400 shrink-0" />
                <div>
                    <h4 className="font-bold text-slate-800 mb-1">Requisitos de Rede</h4>
                    <p className="text-sm text-slate-600 leading-relaxed">
                        Certifique-se que o IP deste terminal está liberado no Firewall do servidor de banco de dados.
                        Conexões via SSL são recomendadas para ambientes de produção.
                    </p>
                </div>
            </div>
        </div>
    </div>
  );
};

