const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/95 backdrop-blur-sm p-3 border border-slate-100 shadow-xl rounded-xl">
        <p className="font-semibold text-slate-700 text-sm mb-1">{label}</p>
        <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-primary-500"></div>
            <p className="text-primary-700 font-bold">
            {payload[0].value} Colaboradores
            </p>
        </div>
      </div>
    );
  }
  return null;
};

export const Dashboard: React.FC = () => {
  const [selectedFilial, setSelectedFilial] = useState<string>('TODAS');
  const [users, setUsers] = useState<User[]>([]);
  const [filialOptions, setFilialOptions] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Simulate Data Fetching
    const loadData = async () => {
        await new Promise(resolve => setTimeout(resolve, 800)); // Simulate delay
        setUsers(dbService.getAllUsers());
        setFilialOptions(dbService.getFiliais());
        setIsLoading(false);
    };
    loadData();
  }, []);

  const filteredUsers = useMemo(() => {
    if (selectedFilial === 'TODAS') return users;
    return users.filter(u => u.filial === selectedFilial);
  }, [selectedFilial, users]);

  const departmentData = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredUsers.forEach(u => {
      counts[u.departamento] = (counts[u.departamento] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [filteredUsers]);

  const sectorData = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredUsers.forEach(u => {
      counts[u.setor] = (counts[u.setor] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [filteredUsers]);

  // Harmonic Cool Palette (Indigo, Violet, Teal, Sky, Blue, Slate)
  const COLORS = ['#6366f1', '#8b5cf6', '#14b8a6', '#0ea5e9', '#3b82f6', '#64748b'];

  if (isLoading) {
      return (
          <div className="flex h-full items-center justify-center min-h-[400px] animate-[fadeIn_0.3s]">
              <div className="flex flex-col items-center gap-4">
                  <div className="relative">
                     <div className="absolute inset-0 bg-primary-200 rounded-full blur-xl opacity-50"></div>
                     <Spinner size="lg" className="relative z-10" />
                  </div>
                  <p className="text-slate-400 text-sm font-medium animate-pulse">Carregando indicadores...</p>
              </div>
          </div>
      );
  }

  return (
    <div className="p-8 space-y-8 animate-[fadeIn_0.4s_ease-out]">

      {/* Header Card */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-6 bg-white p-8 rounded-2xl shadow-soft border border-slate-100 relative overflow-hidden">
        {/* Decorative Background */}
        <div className="absolute top-0 right-0 w-64 h-64 bg-gradient-to-br from-primary-50 to-transparent opacity-50 rounded-bl-[100px] pointer-events-none"></div>

        <div className="w-full md:w-1/3 relative z-10">
           <h2 className="text-sm font-bold text-slate-500 uppercase tracking-widest mb-3 flex items-center gap-2">
             <Filter className="w-4 h-4 text-primary-500"/> 
             Filtrar Dados
           </h2>
           <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                  <Building2 className="h-5 w-5 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
              </div>
              <select
                className="w-full pl-11 pr-10 py-3 bg-slate-50 border border-slate-200 rounded-xl appearance-none focus:ring-2 focus:ring-primary-100 focus:border-primary-500 outline-none text-slate-700 font-medium transition-all cursor-pointer hover:bg-white"
                value={selectedFilial}
                onChange={(e) => {
                    setSelectedFilial(e.target.value);
                }}
              >
                <option value="TODAS">TODAS AS FILIAIS</option>
                {filialOptions.map(f => (
                  <option key={f} value={f}>{f}</option>
                ))}
              </select>
               <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
                  <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
              </div>
           </div>
        </div>

        <div className="flex gap-4 relative z-10">
           <div className="bg-white p-4 pr-10 rounded-xl border border-slate-100 shadow-sm relative overflow-hidden group">
              <div className="absolute right-0 top-0 bottom-0 w-1 bg-gradient-to-b from-primary-400 to-primary-600"></div>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-1">Total Colaboradores</p>
              <div className="flex items-baseline gap-2">
                <p className="text-3xl font-bold text-slate-800 tracking-tight">{filteredUsers.length}</p>
                <span className="text-xs text-green-500 font-medium bg-green-50 px-2 py-0.5 rounded-full">Ativos</span>
              </div>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-2xl shadow-soft border border-slate-100 h-[450px] flex flex-col hover:shadow-lg transition-shadow duration-300">
          <div className="mb-6">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-indigo-50 rounded-lg">
                    <Users className="w-5 h-5 text-indigo-500"/>
                </div>
                Distribuição por Departamento
              </h3>
          </div>
          <div className="flex-1 min-h-0">
            <ResponsiveContainer width="100%" height="100%">
                <BarChart data={departmentData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                    dataKey="name" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{fill: '#94a3b8', fontSize: 11}} 
                    interval={0} 
                    angle={-15}
                    textAnchor="end"
                    height={60}
                />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} />
                <Tooltip content={<CustomTooltip />} cursor={{fill: '#f8fafc'}} />
                <Bar dataKey="value" radius={[6, 6, 0, 0]} animationDuration={1500}>
                    {departmentData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                </Bar>
                </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-2xl shadow-soft border border-slate-100 h-[450px] flex flex-col hover:shadow-lg transition-shadow duration-300">
          <div className="mb-6">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-teal-50 rounded-lg">
                    <TrendingUp className="w-5 h-5 text-teal-500"/>
                </div>
                Distribuição por Setor
              </h3>
          </div>
          <div className="flex-1 min-h-0">
            <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                <Pie
                    data={sectorData}
                    cx="50%"
                    cy="50%"
                    innerRadius={80}
                    outerRadius={120}
                    paddingAngle={4}
                    dataKey="value"
                    cornerRadius={6}
                >
                    {sectorData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />
                    ))}
                </Pie>
                <Tooltip content={<CustomTooltip />} />
                </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { dbService } from '../services/dbService';
import { SystemUser } from '../types';
import { User, Lock, ArrowRight } from 'lucide-react';
import { Spinner } from './Spinner';
