        `}
      >
        <div className="p-6 flex items-center gap-3 shrink-0 bg-slate-950/30">
          <div className="w-10 h-10 flex items-center justify-center shrink-0 bg-gradient-to-tr from-primary-600 to-primary-400 rounded-xl shadow-lg shadow-primary-900/20">
            <Logo className="w-6 h-6" variant="white" />
          </div>
          {isSidebarOpen && (
            <div className="flex flex-col animate-[fadeIn_0.3s]">
                <span className="font-bold text-lg tracking-tight leading-none">K-System</span>
                <span className="text-[10px] text-slate-400 uppercase tracking-widest font-semibold mt-1">Enterprise</span>
            </div>
          )}
        </div>

        <nav className="flex-1 px-4 py-6 space-y-2">
          <div className="pb-2">
             <p className={`px-4 text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3 mt-1 ${!isSidebarOpen && 'hidden'}`}>Principal</p>
             <NavItem view="DASHBOARD" icon={LayoutDashboard} label="Dashboard Geral" />

             {/* REGISTER is visible in menu ONLY for ADMIN, but we secure the component too */}
             {currentUser.role === 'ADMIN' && (
                <NavItem view="REGISTER" icon={UserPlus} label="Novo Cadastro" />
             )}

             <NavItem view="USERS_LIST" icon={Database} label="Base de Dados" />
             <NavItem view="REPORTS" icon={ClipboardList} label="Relatórios" />
          </div>

          {/* Auxiliary Registers - Visible in menu ONLY for ADMIN, but we secure components too */}
          {currentUser.role === 'ADMIN' && (
            <div className="pt-4 mt-2 border-t border-slate-800">
                <p className={`px-4 text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3 ${!isSidebarOpen && 'hidden'}`}>Cadastros Auxiliares</p>
                <NavItem view="REGISTER_FILIAL" icon={Building} label="Cadastrar Filial" />
                <NavItem view="REGISTER_DEPARTAMENTO" icon={Layers} label="Cadastrar Depto." />
                <NavItem view="REGISTER_SETOR" icon={Briefcase} label="Cadastrar Setor" />
            </div>
          )}

          {/* System Settings - Visible in menu ONLY for ADMIN, but we secure components too */}
          {currentUser.role === 'ADMIN' && (
            <div className="pt-4 mt-2 border-t border-slate-800">
               <p className={`px-4 text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3 ${!isSidebarOpen && 'hidden'}`}>Sistema</p>
               <NavItem view="MANAGE_ACCESS" icon={ShieldCheck} label="Usuários de Acesso" />
               <NavItem view="DB_SETTINGS" icon={Settings} label="Configuração BD" />
            </div>
          )}
        </nav>

        <div className="p-4 border-t border-slate-800 shrink-0 bg-slate-950/20">
          <button 
             onClick={() => setCurrentUser(null)}
             className={`
               w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-400 hover:bg-red-500/10 hover:text-red-300 transition-all duration-300 group
               ${!isSidebarOpen && 'justify-center'}
             `}
          >
            <LogOut className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
            {isSidebarOpen && <span className="font-medium">Sair do Sistema</span>}
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative print:block print:h-auto print:overflow-visible print:w-full print:static bg-slate-50/50">
        {/* Top Header with Glassmorphism */}
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200/60 flex items-center justify-between px-8 z-10 shrink-0 print:hidden sticky top-0 transition-all">
           <button 
             onClick={() => setIsSidebarOpen(!isSidebarOpen)}
             className="p-2.5 hover:bg-white rounded-xl text-slate-500 hover:text-primary-600 hover:shadow-sm border border-transparent hover:border-slate-100 transition-all active:scale-95"
           >
             <Menu className="w-6 h-6" />
           </button>

           <div className="flex items-center gap-6">
             <div className="text-right hidden sm:block">
               <p className="text-sm font-bold text-slate-800">{currentUser.nome}</p>
               <div className="flex items-center justify-end gap-1.5">
                   <span className={`w-2 h-2 rounded-full ${currentUser.role === 'ADMIN' ? 'bg-primary-500' : 'bg-slate-400'}`}></span>
                   <p className="text-[11px] text-slate-500 font-medium uppercase tracking-wide">
                       {currentUser.role === 'ADMIN' ? 'Administrador' : 'Convidado'}
                   </p>
               </div>
             </div>
             <div className="w-11 h-11 rounded-full bg-gradient-to-br from-white to-slate-100 border border-slate-200 shadow-sm overflow-hidden flex items-center justify-center text-primary-700">
                <span className="font-bold text-lg">{currentUser.nome.charAt(0)}</span>
             </div>
           </div>
        </header>

        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-auto bg-slate-50 print:overflow-visible print:bg-white print:h-auto print:block scroll-smooth">
          <div className="max-w-7xl mx-auto w-full min-h-full flex flex-col">
            {currentView === 'DASHBOARD' && <Dashboard />}
            {currentView === 'REGISTER' && <RegisterUser userRole={currentUser.role} />}
            {currentView === 'USERS_LIST' && <UsersList onNavigateToRegister={() => setCurrentView('REGISTER')} userRole={currentUser.role} />}
            {currentView === 'REPORTS' && <Reports />}
            {currentView === 'DB_SETTINGS' && <DatabaseSettings userRole={currentUser.role} />}
            {currentView === 'REGISTER_FILIAL' && <ResourceRegister type="FILIAL" userRole={currentUser.role} />}
            {currentView === 'REGISTER_DEPARTAMENTO' && <ResourceRegister type="DEPARTAMENTO" userRole={currentUser.role} />}
            {currentView === 'REGISTER_SETOR' && <ResourceRegister type="SETOR" userRole={currentUser.role} />}
            {currentView === 'MANAGE_ACCESS' && <SystemUsersManagement userRole={currentUser.role} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { User } from '../types';
import { Search, Database, ShieldAlert, Plus, X, CheckCircle2, Eraser, AlertTriangle, Edit2, Trash2, Save, Eye } from 'lucide-react';
import { Spinner } from './Spinner';
import { Input } from './Input';
import { Select } from './Select';

interface UsersListProps {
  onNavigateToRegister?: () => void;
  userRole: 'ADMIN' | 'CONVIDADO';
}

export const UsersList: React.FC<UsersListProps> = ({ onNavigateToRegister, userRole }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  // --- DELETE STATES ---
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [deleteMode, setDeleteMode] = useState<'SINGLE' | 'ALL'>('SINGLE');
  const [userToDelete, setUserToDelete] = useState<User | null>(null);

  // --- DETAILS/EDIT STATES ---
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [editForm, setEditForm] = useState({
      nomeCompleto: '',
      filial: '',
      departamento: '',
      setor: '',
      login: '',
      senha: '' // Optional in edit
  });

  // Options for Edit Form
  const [options, setOptions] = useState({
    filiais: [] as string[],
    departamentos: [] as string[],
    setores: [] as string[]
  });

  useEffect(() => {
    loadUsers();
    // Load options for the edit modal
    setOptions({
        filiais: dbService.getFiliais(),
        departamentos: dbService.getDepartamentos(),
        setores: dbService.getSetores()
    });
  }, []);

  const loadUsers = () => {
    setIsLoading(true);
    setTimeout(() => {
        setUsers(dbService.getAllUsers());
        setIsLoading(false);
    }, 600);
  };

  // --- DELETE LOGIC ---

  const requestDeleteAll = () => {
    setDeleteMode('ALL');
    setIsDeleteModalOpen(true);
  };

  // Called from within the modal for single user deletion
  const requestDeleteSingle = (user: User) => {
    setDeleteMode('SINGLE');
    setUserToDelete(user);
    setIsDetailsModalOpen(false); // Close details modal to show delete confirmation
    setIsDeleteModalOpen(true);
  };

  const handleExecuteDelete = () => {
    setIsProcessing(true);
    setTimeout(() => {
        let result;

        if (deleteMode === 'ALL') {
            result = dbService.deleteAllUsers();
        } else {
            if (userToDelete) {
                result = dbService.deleteUser(userToDelete.id);
            } else {
                result = { success: false, message: "Erro ao identificar usuário." };
            }
        }

        if (result.success) {
            setFeedback({ type: 'success', message: result.message });
            loadUsers();
        } else {
            setFeedback({ type: 'error', message: result.message });
        }

        setIsProcessing(false);
        setIsDeleteModalOpen(false);
        setUserToDelete(null);
        setTimeout(() => setFeedback(null), 3000);
    }, 1000);
  };

  // --- VIEW/EDIT LOGIC ---

  const handleViewClick = (user: User) => {
      setSelectedUser(user);
      setEditForm({
          nomeCompleto: user.nomeCompleto,
          filial: user.filial,
          departamento: user.departamento,
          setor: user.setor,
          login: user.login,
          senha: user.senha || ''
      });
      setIsDetailsModalOpen(true);
  };

  const handleSaveEdit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!selectedUser) return;
      if (userRole !== 'ADMIN') return;

      setIsProcessing(true);

      const updatedUser: User = {
          ...selectedUser,
          nomeCompleto: editForm.nomeCompleto.toUpperCase(),
          filial: editForm.filial,
          departamento: editForm.departamento,
          setor: editForm.setor,
          login: editForm.login.toUpperCase(),
          senha: editForm.senha // If empty, service logic might need adjustment, but usually we overwrite
      };

      setTimeout(() => {
          const result = dbService.updateUser(updatedUser);

          if (result.success) {
              setFeedback({ type: 'success', message: result.message });
              loadUsers();
              setIsDetailsModalOpen(false);
              setSelectedUser(null);
          } else {
              setFeedback({ type: 'error', message: result.message }); // Likely login duplicate
          }

          setIsProcessing(false);
          setTimeout(() => setFeedback(null), 3000);
      }, 800);
  };

  // Optimized Search Logic
  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) return users;

    return users.filter(user =>
      user.nomeCompleto.toLowerCase().includes(term) ||
      user.matricula.includes(term) ||
      user.filial.toLowerCase().includes(term) ||
      user.departamento.toLowerCase().includes(term) ||
      user.setor.toLowerCase().includes(term) ||
      user.login.toLowerCase().includes(term)
    );
  }, [users, searchTerm]);

  return (
    <div className="h-full p-6 flex flex-col gap-6 animate-[fadeIn_0.4s_ease-out] print:p-0 print:space-y-0">

        {feedback && !isDeleteModalOpen && !isDetailsModalOpen && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            } print:hidden`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <ShieldAlert className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

        {/* Print Header */}
        <div className="hidden print:block mb-8 border-b-2 border-slate-100 pb-6">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Relatório Geral de Usuários</h1>
                    <p className="text-slate-500 text-sm mt-1">K-System Enterprise - Base de Dados Completa</p>
                </div>
                <div className="text-right">
                    <p className="text-xs text-slate-400 uppercase tracking-wider font-semibold">Data de Emissão</p>
                    <p className="text-slate-900 font-mono">{new Date().toLocaleString()}</p>
                </div>
            </div>
            {searchTerm && (
                <div className="mt-4 p-2 bg-slate-50 border border-slate-200 rounded text-sm text-slate-600 inline-block">
                    Filtro aplicado: <span className="font-semibold">"{searchTerm}"</span>
                </div>
            )}
        </div>

        <div className="flex-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col min-h-0 print:shadow-none print:border-none print:p-0 print:min-h-0">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6 print:hidden">
                <div>
                    <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        <Database className="w-6 h-6 text-primary-500"/>
                        Base de Dados de Usuários
                    </h2>
                    <p className="text-slate-500 text-sm mt-1">Gerenciamento completo dos registros do sistema</p>
                </div>

                <div className="flex gap-3 w-full md:w-auto flex-wrap md:flex-nowrap justify-end">
                    <div className="relative flex-1 md:w-80 group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
                        <input
                            type="text"
                            placeholder="Buscar por matrícula, nome, filial, login..."
                            className="w-full pl-10 pr-10 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all text-sm"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            disabled={isLoading}
                        />
                        {searchTerm && (
                            <button 
                                onClick={() => setSearchTerm('')}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 rounded-full hover:bg-slate-200 transition-colors"
                                title="Limpar busca"
                            >
                                <X className="w-3 h-3" />
                            </button>
                        )}
                    </div>

                    {userRole === 'ADMIN' && users.length > 0 && (
                        <button 
                            type="button"
                            onClick={requestDeleteAll}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-red-50 text-red-600 border border-red-100 px-4 py-2.5 rounded-xl hover:bg-red-100 transition-colors font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Eraser className="w-4 h-4" />
                            Limpar Base
                        </button>
                    )}

                    {userRole === 'ADMIN' && onNavigateToRegister && (
                        <button 
                            type="button"
                            onClick={onNavigateToRegister}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2.5 rounded-xl hover:bg-primary-700 transition-colors shadow-lg shadow-primary-500/20 font-medium text-sm whitespace-nowrap disabled:opacity-50"
                        >
                            <Plus className="w-4 h-4" />
                            Novo Usuário
                        </button>
                    )}
                </div>
            </div>

            <div className="flex-1 overflow-auto rounded-xl border border-slate-200 shadow-sm print:overflow-visible print:shadow-none print:border-none print:rounded-none">
                <table className="w-full text-left border-collapse relative">
                    <thead className="print:bg-slate-100 sticky top-0 z-10 bg-slate-50/95 backdrop-blur-sm border-b border-slate-200">
                        <tr>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Matrícula</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Nome Completo</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Filial</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Departamento / Setor</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider print:text-slate-900">Login</th>
                            <th className="p-4 font-semibold text-slate-600 text-xs uppercase tracking-wider text-right print:hidden">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 bg-white">
                        {isLoading ? (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                     <div className="flex flex-col items-center justify-center gap-3">
                                        <Spinner size="lg" />
                                        <p className="text-slate-400 font-medium">Carregando registros...</p>
                                     </div>
                                </td>
                            </tr>
                        ) : filteredUsers.length > 0 ? (
                            filteredUsers.map((user) => (
                                <tr key={user.id} className="hover:bg-slate-50/80 transition-colors group print:break-inside-avoid">
                                    <td className="p-4 text-sm text-slate-600 font-mono font-medium print:text-slate-800">{user.matricula}</td>
                                    <td className="p-4">
                                        <div className="font-semibold text-slate-800 text-sm print:text-black">{user.nomeCompleto}</div>
                                        <div className="text-xs text-slate-400">Cadastrado em {new Date(user.dataCadastro).toLocaleDateString()}</div>
                                    </td>
                                    <td className="p-4">
                                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-100 print:bg-transparent print:border-none print:p-0 print:text-slate-800">
                                            {user.filial}
                                        </span>
                                    </td>
                                    <td className="p-4">
                                        <div className="text-sm text-slate-700 print:text-slate-800">{user.departamento}</div>
                                        <div className="text-xs text-slate-500">{user.setor}</div>
                                    </td>
                                    <td className="p-4 text-sm text-slate-600 font-mono bg-slate-50/50 rounded w-fit px-2 print:bg-transparent print:p-0 print:text-slate-800">{user.login}</td>

                                    {/* Action Column - VISUALIZAR Only */}
                                    <td className="p-4 text-right print:hidden">
                                        <button 
                                            onClick={() => handleViewClick(user)}
                                            className="p-2 text-slate-400 hover:text-primary-600 hover:bg-primary-50 rounded-lg transition-all"
                                            title="Visualizar"
                                        >
                                            <Eye className="w-5 h-5" />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={6} className="p-12 text-center">
                                    <div className="flex flex-col items-center justify-center text-slate-400">
                                        <ShieldAlert className="w-12 h-12 mb-3 text-slate-300" />
                                        <p className="text-lg font-medium text-slate-500">
                                            {searchTerm ? `Nenhum resultado para "${searchTerm}"` : 'Nenhum registro encontrado'}
                                        </p>
                                        {searchTerm && (
                                            <button 
                                                onClick={() => setSearchTerm('')}
                                                className="mt-2 text-primary-600 hover:text-primary-700 text-sm font-medium hover:underline print:hidden"
                                            >
                                                Limpar filtros
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            <div className="mt-4 flex justify-between items-center text-xs text-slate-400 pt-2 print:hidden">
                <p>Mostrando {filteredUsers.length} de {users.length} registros</p>
            </div>
             {/* Print Footer */}
             <div className="hidden print:flex mt-4 pt-4 border-t border-slate-200 justify-between text-xs text-slate-500">
                <p>K-System Enterprise - Relatório Administrativo</p>
                <p>Total: {filteredUsers.length}</p>
            </div>
        </div>

        {/* --- DETAILS / EDIT MODAL --- */}
        {isDetailsModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s] print:hidden">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 bg-primary-900 flex justify-between items-center">
                        <h3 className="text-xl font-bold text-white flex items-center gap-2">
                            {userRole === 'ADMIN' ? <Edit2 className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            {userRole === 'ADMIN' ? 'Editar Colaborador' : 'Detalhes do Colaborador'}
                        </h3>
                        <button onClick={() => setIsDetailsModalOpen(false)} className="text-primary-200 hover:text-white transition-colors">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <form onSubmit={handleSaveEdit} className="p-8">
                        {feedback && (
                            <div className="mb-6 p-3 bg-red-50 border border-red-200 text-red-700 rounded-lg text-sm flex items-center gap-2">
                                <AlertTriangle className="w-4 h-4" />
                                {feedback.message}
                            </div>
                        )}

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="col-span-1 md:col-span-2">
                                <Input 
                                    label="Nome Completo" 
                                    value={editForm.nomeCompleto} 
                                    onChange={e => setEditForm({...editForm, nomeCompleto: e.target.value.toUpperCase()})}
                                    required
                                    disabled={userRole !== 'ADMIN'}
                                />
                            </div>

                            <Select 
                                label="Filial" 
                                options={options.filiais}
                                value={editForm.filial}
                                onChange={e => setEditForm({...editForm, filial: e.target.value})}
                                required
                                disabled={userRole !== 'ADMIN'}
                            />

                            <Input 
                                label="Login" 
                                value={editForm.login}
                                onChange={e => setEditForm({...editForm, login: e.target.value.toUpperCase()})}
                                required
                                disabled={userRole !== 'ADMIN'}
                            />

                            <Select 
                                label="Departamento" 
                                options={options.departamentos}
                                value={editForm.departamento}
                                onChange={e => setEditForm({...editForm, departamento: e.target.value})}
                                required
                                disabled={userRole !== 'ADMIN'}
                            />

                            <Select 
                                label="Setor" 
                                options={options.setores}
                                value={editForm.setor}
                                onChange={e => setEditForm({...editForm, setor: e.target.value})}
                                required
                                disabled={userRole !== 'ADMIN'}
                            />

                            {userRole === 'ADMIN' && (
                                <div className="col-span-1 md:col-span-2 border-t border-slate-100 pt-4 mt-2">
                                    <label className="block text-sm font-medium text-slate-700 mb-1">Nova Senha (Opcional)</label>
                                    <input 
                                        type="password"
                                        className="w-full px-4 py-2 bg-white border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary-500 outline-none"
                                        placeholder="Deixe em branco para manter a atual"
                                        value={editForm.senha}
                                        onChange={e => setEditForm({...editForm, senha: e.target.value})}
                                    />
                                </div>
                            )}
                        </div>

                        <div className="flex justify-between items-center mt-8 pt-4 border-t border-slate-100">
                             {/* Left Side: Delete Button (Admin Only) */}
                             <div>
                                {userRole === 'ADMIN' && selectedUser && (
                                    <button 
                                        type="button"
                                        onClick={() => requestDeleteSingle(selectedUser)}
                                        className="text-red-500 hover:text-red-700 hover:bg-red-50 px-4 py-2 rounded-lg transition-colors flex items-center gap-2 text-sm font-medium"
                                        disabled={isProcessing}
                                    >
                                        <Trash2 className="w-4 h-4" />
                                        Excluir Cadastro
                                    </button>
                                )}
                             </div>

                             {/* Right Side: Action Buttons */}
                             <div className="flex gap-3">
                                <button 
                                    type="button"
                                    onClick={() => setIsDetailsModalOpen(false)}
                                    disabled={isProcessing}
                                    className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium disabled:opacity-50"
                                >
                                    {userRole === 'ADMIN' ? 'Cancelar' : 'Fechar'}
                                </button>

                                {userRole === 'ADMIN' && (
                                    <button 
                                        type="submit"
                                        disabled={isProcessing}
                                        className="px-5 py-2.5 bg-primary-600 text-white rounded-xl hover:bg-primary-700 transition-colors font-medium shadow-lg shadow-primary-500/30 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                                    >
                                        {isProcessing ? <Spinner size="sm" variant="white" /> : <Save className="w-4 h-4" />}
                                        {isProcessing ? "Salvando..." : "Salvar Alterações"}
                                    </button>
                                )}
                            </div>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* --- DELETE CONFIRMATION MODAL (Handles both Single and All) --- */}
        {isDeleteModalOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s] print:hidden">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-[scaleIn_0.2s_ease-out]">
                    <div className="p-6 text-center">
                        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <AlertTriangle className="w-8 h-8 text-red-600" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-800 mb-2">Confirmar Exclusão</h3>
                        <p className="text-slate-500 mb-6">
                            {deleteMode === 'ALL' 
                                ? 'Você está prestes a excluir TODOS os registros da base de dados. Esta ação é irreversível.' 
                                : `Tem certeza que deseja excluir o usuário "${userToDelete?.nomeCompleto}"?`}
                        </p>

                        <div className="flex gap-3 justify-center">
                            <button 
                                onClick={() => setIsDeleteModalOpen(false)}
                                disabled={isProcessing}
                                className="px-5 py-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors font-medium disabled:opacity-50"
                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={handleExecuteDelete}
                                disabled={isProcessing}
                                className="px-5 py-2.5 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors font-medium shadow-lg shadow-red-500/30 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                            >
                                {isProcessing ? <Spinner size="sm" variant="white" /> : <Eraser className="w-4 h-4" />}
                                {isProcessing ? "Processando..." : (deleteMode === 'ALL' ? "Sim, Limpar Tudo" : "Sim, Excluir")}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Input } from './Input';
import { Select } from './Select';
import { Database, Server, Save, Activity, CheckCircle2, XCircle, Lock } from 'lucide-react';
import { Spinner } from './Spinner';

interface DatabaseSettingsProps {
    userRole: 'ADMIN' | 'CONVIDADO';
}

export const DatabaseSettings: React.FC<DatabaseSettingsProps> = ({ userRole }) => {
  const [config, setConfig] = useState({
    type: '',
    host: '',
    port: '',
    database: '',
    user: '',
    password: ''
  });

  const [status, setStatus] = useState<'DISCONNECTED' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');
  const [lastCheck, setLastCheck] = useState<string | null>(null);

  // Load saved config on mount
  useEffect(() => {
    const saved = localStorage.getItem('k_system_db_config');
    if (saved) {
      setConfig(JSON.parse(saved));
      // Optionally simulate that we are already connected if config exists
      setStatus('CONNECTED');
      setLastCheck(new Date().toLocaleTimeString());
    }
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setConfig({ ...config, [e.target.name]: e.target.value });
    if (status === 'CONNECTED' || status === 'ERROR') {
        setStatus('DISCONNECTED'); // Reset status on change
    }
  };

  const handleTestConnection = (e: React.FormEvent) => {
    e.preventDefault();

    if (userRole !== 'ADMIN') return;

    if (!config.type || !config.host || !config.user) {
        setStatus('ERROR');
        return;
    }

    setStatus('CONNECTING');

    // Simulate network request
    setTimeout(() => {
        // Simple mock validation logic
        if (config.host.includes('.') || config.host === 'localhost') {
            setStatus('CONNECTED');
            setLastCheck(new Date().toLocaleTimeString());
            localStorage.setItem('k_system_db_config', JSON.stringify(config));
        } else {
            setStatus('ERROR');
        }
    }, 2000);
  };

  const isDisabled = userRole !== 'ADMIN';

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="bg-primary-900 p-6 flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        <Server className="w-6 h-6 text-primary-200"/>
                        Configuração de Conexão
                    </h2>
                    <p className="text-primary-200 text-sm mt-1">Gerencie a conexão com o banco de dados externo.</p>
                </div>
                <div className="hidden sm:flex items-center gap-3 bg-primary-800 px-4 py-2 rounded-lg border border-primary-700">
                    <div className="text-right">
                        <p className="text-xs text-primary-200 uppercase tracking-wider font-semibold">Status Atual</p>
                        <p className={`text-sm font-bold flex items-center justify-end gap-1.5 ${
                            status === 'CONNECTED' ? 'text-green-400' : 
                            status === 'CONNECTING' ? 'text-yellow-400' : 
                            status === 'ERROR' ? 'text-red-300' : 'text-slate-300'
                        }`}>
                            {status === 'CONNECTED' && <CheckCircle2 className="w-4 h-4" />}
                            {status === 'ERROR' && <XCircle className="w-4 h-4" />}
                            {status === 'CONNECTING' && <Spinner size="sm" variant="white" />}
                            {status === 'DISCONNECTED' && <Activity className="w-4 h-4" />}
                            {status === 'CONNECTED' ? 'CONECTADO' : 
                             status === 'CONNECTING' ? 'CONECTANDO...' : 
                             status === 'ERROR' ? 'FALHA NA CONEXÃO' : 'DESCONECTADO'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="p-8">
                {isDisabled && (
                    <div className="mb-6 p-4 bg-yellow-50 border border-yellow-100 rounded-lg flex items-center gap-3 text-yellow-800 text-sm">
                        <Lock className="w-5 h-5" />
                        <span>Modo de Leitura: Apenas administradores podem alterar as configurações de conexão.</span>
                    </div>
                )}

                <form onSubmit={handleTestConnection}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                        <div className="col-span-1 md:col-span-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Parâmetros do Servidor
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Select 
                                label="Tipo de Banco de Dados"
                                name="type"
                                options={['MySQL', 'PostgreSQL', 'Oracle', 'SQL Server', 'MariaDB']}
                                value={config.type}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Nome da Base (Database)"
                                name="database"
                                placeholder="ex: k_system_prod"
                                value={config.database}
                                onChange={handleChange}
                                disabled={isDisabled}
                            />
                        </div>

                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Host / IP"
                                name="host"
                                placeholder="ex: 192.168.1.50"
                                value={config.host}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Porta"
                                name="port"
                                placeholder="ex: 3306"
                                value={config.port}
                                onChange={handleChange}
                                type="number"
                                disabled={isDisabled}
                            />
                        </div>

                        <div className="col-span-1 md:col-span-2 mt-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Credenciais de Acesso
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Input 
                                label="Usuário"
                                name="user"
                                placeholder="root"
                                value={config.user}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Senha"
                                name="password"
                                type="password"
                                placeholder="••••••••"
                                value={config.password}
                                onChange={handleChange}
                                disabled={isDisabled}
                            />
                        </div>
                    </div>

                    <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                        <div className="text-xs text-slate-400">
                            {lastCheck && <span>Última verificação: {lastCheck}</span>}
                        </div>
                        {userRole === 'ADMIN' && (
                            <div className="flex gap-3">
                                <button
                                    type="button" 
                                    onClick={() => {
                                        setConfig({ type: '', host: '', port: '', database: '', user: '', password: '' });
                                        setStatus('DISCONNECTED');
                                        localStorage.removeItem('k_system_db_config');
                                    }}
                                    className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-xl transition-colors"
                                >
                                    Limpar
                                </button>
                                <button 
                                    type="submit"
                                    disabled={status === 'CONNECTING'}
                                    className={`
                                        flex items-center gap-2 px-8 py-2.5 bg-primary-600 text-white rounded-xl font-semibold shadow-lg shadow-primary-500/30 hover:bg-primary-700 transition-all active:scale-95
                                        ${status === 'CONNECTING' ? 'opacity-70 cursor-not-allowed' : ''}
                                    `}
                                >
                                    {status === 'CONNECTING' ? (
                                        <>
                                            <Spinner size="sm" variant="white" />
                                            <span>Verificando...</span>
                                        </>
                                    ) : (
                                        <>
                                            <Save className="w-5 h-5" />
                                            Salvar e Conectar
                                        </>
                                    )}
                                </button>
                            </div>
                        )}
                    </div>
                </form>
            </div>
        </div>

        {/* Info Card */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-red-50 border border-red-100 p-6 rounded-xl flex items-start gap-4">
                <Database className="w-8 h-8 text-red-500 shrink-0" />
                <div>
                    <h4 className="font-bold text-red-900 mb-1">Modo Híbrido</h4>
                    <p className="text-sm text-red-700 leading-relaxed">
                        O sistema operará em modo offline (Local Storage) caso a conexão com o servidor falhe.
                    </p>
                </div>
            </div>
            <div className="bg-slate-50 border border-slate-200 p-6 rounded-xl flex items-start gap-4 md:col-span-2">
                <Server className="w-8 h-8 text-slate-400 shrink-0" />
                <div>
                    <h4 className="font-bold text-slate-800 mb-1">Requisitos de Rede</h4>
                    <p className="text-sm text-slate-600 leading-relaxed">
                        Certifique-se que o IP deste terminal está liberado no Firewall do servidor de banco de dados.
                        Conexões via SSL são recomendadas para ambientes de produção.
                    </p>
                </div>
            </div>
        </div>
    </div>
  );
};

