const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-slate-900/95 backdrop-blur-md p-4 rounded-xl shadow-2xl border border-slate-700/50 min-w-[150px] animate-in fade-in zoom-in-95 duration-200">
        <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 border-b border-slate-700 pb-2">{label}</p>
        <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-2">
                <div className="w-2.5 h-2.5 rounded-full bg-primary-500 shadow-[0_0_10px_rgba(99,102,241,0.5)]"></div>
                <span className="text-sm font-medium text-slate-200">Total</span>
            </div>
            <p className="text-xl font-bold text-white tracking-tight">
            {payload[0].value}
            </p>
        </div>
      </div>
    );
  }
  return null;
};

export const Dashboard: React.FC = () => {
