import React, { useState, useEffect, useRef } from 'react';
import { ViewState, SystemUser } from './types';
import { Login } from './components/Login';
import { RegisterUser } from './components/RegisterUser';
import { Dashboard } from './components/Dashboard';
import { UsersList } from './components/UsersList';
import { Reports } from './components/Reports';
import { DatabaseSettings } from './components/DatabaseSettings';
import { ResourceRegister } from './components/ResourceRegister';
import { SystemUsersManagement } from './components/SystemUsersManagement';
import { Logo } from './components/Logo';
import { LayoutDashboard, UserPlus, LogOut, Menu, Database, ClipboardList, Settings, Layers, Building, Briefcase, ShieldCheck } from 'lucide-react';

// 15 Minutes in milliseconds
const INACTIVITY_TIMEOUT = 15 * 60 * 1000; 

const App: React.FC = () => {
  // Now storing the full user object instead of just boolean
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // --- AUTO LOGOUT LOGIC ---
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (!currentUser) return;

    const handleLogout = () => {
      // Optional: You could save a flag in localStorage to show a "Session Expired" message on the login screen
      setCurrentUser(null);
    };

    const resetTimer = () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
      timerRef.current = setTimeout(handleLogout, INACTIVITY_TIMEOUT);
    };

    // Events to track user activity
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart'];

    // Attach listeners
    events.forEach(event => {
      document.addEventListener(event, resetTimer);
    });

    // Start initial timer
    resetTimer();

    // Cleanup listeners and timer on unmount or logout
    return () => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
      events.forEach(event => {
        document.removeEventListener(event, resetTimer);
      });
    };
  }, [currentUser]);
  // -------------------------

  if (!currentUser) {
    return <Login onLoginSuccess={(user) => setCurrentUser(user)} />;
  }

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState, icon: any, label: string }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`
