import React, { useState, useEffect } from 'react';
import { dbService } from '../services/dbService.ts';
import { Input } from './Input.tsx';
import { Select } from './Select.tsx';
import { Save, AlertCircle, CheckCircle2, ShieldAlert } from 'lucide-react';
import { Spinner } from './Spinner.tsx';

interface RegisterUserProps {
  userRole?: 'ADMIN' | 'CONVIDADO';
}

export const RegisterUser: React.FC<RegisterUserProps> = ({ userRole = 'CONVIDADO' }) => {
  const [formData, setFormData] = useState({
    matricula: '',
    nomeCompleto: '',
    filial: '',
    login: '',
    senha: '',
    departamento: '',
    setor: ''
  });

  const [isSaving, setIsSaving] = useState(false);

  // Dynamic Options States
  const [options, setOptions] = useState({
      filiais: [] as string[],
      departamentos: [] as string[],
      setores: [] as string[]
  });

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [fieldErrors, setFieldErrors] = useState<{ login?: string }>({});

  useEffect(() => {
    // Load dynamic options from DB
    setOptions({
        filiais: dbService.getFiliais(),
        departamentos: dbService.getDepartamentos(),
        setores: dbService.getSetores()
    });
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    // Apply Uppercase constraints immediately
    let finalValue = value;
    if (['nomeCompleto', 'login'].includes(name)) {
        finalValue = value.toUpperCase();
    }

    setFormData(prev => ({ ...prev, [name]: finalValue }));

    // Clear field specific error when user starts typing again
    if (name === 'login') {
        setFieldErrors(prev => ({ ...prev, login: undefined }));
    }

    if (feedback) setFeedback(null);
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      const { name, value } = e.target;
      if (name === 'login' && value) {
          const exists = dbService.checkLoginExists(value);
          if (exists) {
              setFieldErrors(prev => ({ ...prev, login: `O login ${value} já está em uso.` }));
          }
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (Object.values(formData).some(x => x === '')) {
        setFeedback({ type: 'error', message: 'Por favor, preencha todos os campos.' });
        return;
    }

    if (fieldErrors.login) {
        setFeedback({ type: 'error', message: 'Corrija os erros do formulário antes de salvar.' });
        return;
    }

    setIsSaving(true);
    // Simulate API delay
    setTimeout(() => {
        const result = dbService.addUser({
            ...formData
        });

        if (result.success) {
            setFeedback({ type: 'success', message: result.message });
            setFormData({
                matricula: '',
                nomeCompleto: '',
                filial: '',
                login: '',
                senha: '',
                departamento: '',
                setor: ''
            });
        } else {
            setFeedback({ type: 'error', message: result.message });
        }
        setIsSaving(false);
    }, 1000);
  };

  if (userRole !== 'ADMIN') {
      return (
          <div className="flex h-full items-center justify-center p-6 animate-[fadeIn_0.3s]">
              <div className="bg-white p-8 rounded-2xl shadow-xl text-center max-w-md">
                  <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                      <ShieldAlert className="w-8 h-8 text-red-600" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800 mb-2">Acesso Restrito</h2>
                  <p className="text-slate-500">
                      Seu nível de acesso (CONVIDADO) não permite realizar novos cadastros. Solicite permissão ao administrador.
                  </p>
              </div>
          </div>
      );
  }

  return (
    <div className="max-w-4xl mx-auto p-6 animate-[fadeIn_0.3s_ease-out]">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden">
        <div className="bg-primary-900 p-6 flex items-center justify-between">
            <div>
                <h2 className="text-2xl font-bold text-white">Novo Colaborador</h2>
                <p className="text-primary-100 text-sm mt-1">Preencha os dados abaixo para cadastrar um novo usuário no sistema.</p>
            </div>
            <div className="hidden sm:block text-right">
                <p className="text-primary-200 text-xs uppercase tracking-wider">Data do Cadastro</p>
                <p className="text-white font-mono">{new Date().toLocaleDateString()}</p>
            </div>
        </div>

        <form onSubmit={handleSubmit} className="p-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

                {/* ID and Branch Row */}
                <div className="col-span-1">
                    <Input 
                        label="Matrícula"
                        name="matricula"
                        type="number"
                        placeholder="Ex: 1005"
                        value={formData.matricula}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                     <Select
                        label="Filial"
                        name="filial"
                        value={formData.filial}
                        onChange={handleChange}
                        options={options.filiais}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Name Row */}
                <div className="col-span-1 md:col-span-2">
                    <Input 
                        label="Nome Completo (Automático Caixa Alta)"
                        name="nomeCompleto"
                        type="text"
                        placeholder="NOME DO FUNCIONÁRIO"
                        value={formData.nomeCompleto}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Login Info */}
                <div className="col-span-1">
                    <Input 
                        label="Login (Automático Caixa Alta)"
                        name="login"
                        type="text"
                        placeholder="USUARIO.LOGIN"
                        value={formData.login}
                        onChange={handleChange}
                        onBlur={handleBlur}
                        error={fieldErrors.login}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                    <Input 
                        label="Senha"
                        name="senha"
                        type="password"
                        placeholder="••••••••"
                        value={formData.senha}
                        onChange={handleChange}
                        required
                        disabled={isSaving}
                    />
                </div>

                {/* Job Info */}
                <div className="col-span-1">
                    <Select
                        label="Departamento"
                        name="departamento"
                        value={formData.departamento}
                        onChange={handleChange}
                        options={options.departamentos}
                        required
                        disabled={isSaving}
                    />
                </div>
                <div className="col-span-1">
                     <Select
                        label="Setor"
                        name="setor"
                        value={formData.setor}
                        onChange={handleChange}
                        options={options.setores}
                        required
                        disabled={isSaving}
                    />
                </div>
            </div>

            {/* Feedback Message */}
            {feedback && (
                <div className={`mt-6 p-4 rounded-lg flex items-center gap-3 ${feedback.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                    {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                    <span className="font-medium">{feedback.message}</span>
                </div>
            )}

            <div className="mt-8 flex justify-end">
                <button 
                    type="submit"
                    disabled={isSaving}
                    className="flex items-center gap-2 bg-primary-600 text-white px-8 py-3 rounded-xl hover:bg-primary-700 active:scale-95 transition-all shadow-lg shadow-primary-500/30 font-semibold disabled:opacity-70 disabled:cursor-not-allowed"
                >
                    {isSaving ? <Spinner size="sm" variant="white" /> : <Save className="w-5 h-5" />}
                    {isSaving ? 'Salvando...' : 'Salvar Cadastro'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

