import React, { useState, useEffect } from 'react';
import { Input } from './Input.tsx';
import { Select } from './Select.tsx';
import { Database, Server, Save, Activity, CheckCircle2, XCircle, Lock } from 'lucide-react';
import { Spinner } from './Spinner.tsx';

interface DatabaseSettingsProps {
    userRole: 'ADMIN' | 'CONVIDADO';
}

export const DatabaseSettings: React.FC<DatabaseSettingsProps> = ({ userRole }) => {
  const [config, setConfig] = useState({
    type: '',
    host: '',
    port: '',
    database: '',
    user: '',
    password: ''
  });

  const [status, setStatus] = useState<'DISCONNECTED' | 'CONNECTING' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');
  const [lastCheck, setLastCheck] = useState<string | null>(null);

  // Load saved config on mount
  useEffect(() => {
    const saved = localStorage.getItem('k_system_db_config');
    if (saved) {
      setConfig(JSON.parse(saved));
      // Optionally simulate that we are already connected if config exists
      setStatus('CONNECTED');
      setLastCheck(new Date().toLocaleTimeString());
    }
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setConfig({ ...config, [e.target.name]: e.target.value });
    if (status === 'CONNECTED' || status === 'ERROR') {
        setStatus('DISCONNECTED'); // Reset status on change
    }
  };

  const handleTestConnection = (e: React.FormEvent) => {
    e.preventDefault();

    if (userRole !== 'ADMIN') return;

    if (!config.type || !config.host || !config.user) {
        setStatus('ERROR');
        return;
    }

    setStatus('CONNECTING');

    // Simulate network request
    setTimeout(() => {
        // Simple mock validation logic
        if (config.host.includes('.') || config.host === 'localhost') {
            setStatus('CONNECTED');
            setLastCheck(new Date().toLocaleTimeString());
            localStorage.setItem('k_system_db_config', JSON.stringify(config));
        } else {
            setStatus('ERROR');
        }
    }, 2000);
  };

  const isDisabled = userRole !== 'ADMIN';

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="bg-primary-900 p-6 flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        <Server className="w-6 h-6 text-primary-200"/>
                        Configuração de Conexão
                    </h2>
                    <p className="text-primary-200 text-sm mt-1">Gerencie a conexão com o banco de dados externo.</p>
                </div>
                <div className="hidden sm:flex items-center gap-3 bg-primary-800 px-4 py-2 rounded-lg border border-primary-700">
                    <div className="text-right">
                        <p className="text-xs text-primary-200 uppercase tracking-wider font-semibold">Status Atual</p>
                        <p className={`text-sm font-bold flex items-center justify-end gap-1.5 ${
                            status === 'CONNECTED' ? 'text-green-400' : 
                            status === 'CONNECTING' ? 'text-yellow-400' : 
                            status === 'ERROR' ? 'text-red-300' : 'text-slate-300'
                        }`}>
                            {status === 'CONNECTED' && <CheckCircle2 className="w-4 h-4" />}
                            {status === 'ERROR' && <XCircle className="w-4 h-4" />}
                            {status === 'CONNECTING' && <Spinner size="sm" variant="white" />}
                            {status === 'DISCONNECTED' && <Activity className="w-4 h-4" />}
                            {status === 'CONNECTED' ? 'CONECTADO' : 
                             status === 'CONNECTING' ? 'CONECTANDO...' : 
                             status === 'ERROR' ? 'FALHA NA CONEXÃO' : 'DESCONECTADO'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="p-8">
                {isDisabled && (
                    <div className="mb-6 p-4 bg-yellow-50 border border-yellow-100 rounded-lg flex items-center gap-3 text-yellow-800 text-sm">
                        <Lock className="w-5 h-5" />
                        <span>Modo de Leitura: Apenas administradores podem alterar as configurações de conexão.</span>
                    </div>
                )}

                <form onSubmit={handleTestConnection}>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                        <div className="col-span-1 md:col-span-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Parâmetros do Servidor
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Select 
                                label="Tipo de Banco de Dados"
                                name="type"
                                options={['MySQL', 'PostgreSQL', 'Oracle', 'SQL Server', 'MariaDB']}
                                value={config.type}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Nome da Base (Database)"
                                name="database"
                                placeholder="ex: k_system_prod"
                                value={config.database}
                                onChange={handleChange}
                                disabled={isDisabled}
                            />
                        </div>

                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Host / IP"
                                name="host"
                                placeholder="ex: 192.168.1.50"
                                value={config.host}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1 md:col-span-1">
                            <Input 
                                label="Porta"
                                name="port"
                                placeholder="ex: 3306"
                                value={config.port}
                                onChange={handleChange}
                                type="number"
                                disabled={isDisabled}
                            />
                        </div>

                        <div className="col-span-1 md:col-span-2 mt-2">
                            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wide mb-4 border-b border-slate-100 pb-2">
                                Credenciais de Acesso
                            </h3>
                        </div>

                        <div className="col-span-1">
                            <Input 
                                label="Usuário"
                                name="user"
                                placeholder="root"
                                value={config.user}
                                onChange={handleChange}
                                required
                                disabled={isDisabled}
                            />
                        </div>
                        <div className="col-span-1">
                            <Input 
                                label="Senha"
                                name="password"
                                type="password"
                                placeholder="••••••••"
                                value={config.password}
                                onChange={handleChange}
                                disabled={isDisabled}
                            />
                        </div>
                    </div>

                    <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                        <div className="text-xs text-slate-400">
                            {lastCheck && <span>Última verificação: {lastCheck}</span>}
                        </div>
                        {userRole === 'ADMIN' && (
                            <div className="flex gap-3">
                                <button
                                    type="button" 
                                    onClick={() => {
                                        setConfig({ type: '', host: '', port: '', database: '', user: '', password: '' });
                                        setStatus('DISCONNECTED');
                                        localStorage.removeItem('k_system_db_config');
                                    }}
                                    className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-xl transition-colors"
                                >
                                    Limpar
                                </button>
                                <button 
                                    type="submit"
                                    disabled={status === 'CONNECTING'}
                                    className={`
                                        flex items-center gap-2 px-8 py-2.5 bg-primary-600 text-white rounded-xl font-semibold shadow-lg shadow-primary-500/30 hover:bg-primary-700 transition-all active:scale-95
                                        ${status === 'CONNECTING' ? 'opacity-70 cursor-not-allowed' : ''}
                                    `}
                                >
                                    {status === 'CONNECTING' ? (
                                        <>
                                            <Spinner size="sm" variant="white" />
                                            <span>Verificando...</span>
                                        </>
                                    ) : (
                                        <>
                                            <Save className="w-5 h-5" />
                                            Salvar e Conectar
                                        </>
                                    )}
                                </button>
                            </div>
                        )}
                    </div>
                </form>
            </div>
        </div>

        {/* Info Card */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-red-50 border border-red-100 p-6 rounded-xl flex items-start gap-4">
                <Database className="w-8 h-8 text-red-500 shrink-0" />
                <div>
                    <h4 className="font-bold text-red-900 mb-1">Modo Híbrido</h4>
                    <p className="text-sm text-red-700 leading-relaxed">
                        O sistema operará em modo offline (Local Storage) caso a conexão com o servidor falhe.
                    </p>
                </div>
            </div>
            <div className="bg-slate-50 border border-slate-200 p-6 rounded-xl flex items-start gap-4 md:col-span-2">
                <Server className="w-8 h-8 text-slate-400 shrink-0" />
                <div>
                    <h4 className="font-bold text-slate-800 mb-1">Requisitos de Rede</h4>
                    <p className="text-sm text-slate-600 leading-relaxed">
                        Certifique-se que o IP deste terminal está liberado no Firewall do servidor de banco de dados.
                        Conexões via SSL são recomendadas para ambientes de produção.
                    </p>
                </div>
            </div>
        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { dbService } from '../services/dbService.ts';
import { Plus, Trash2, List, Save, Building, Briefcase, Layers, CheckCircle2, AlertCircle, X, AlertTriangle } from 'lucide-react';
import { Input } from './Input.tsx';
import { Spinner } from './Spinner.tsx';

interface ResourceRegisterProps {
  type: 'FILIAL' | 'DEPARTAMENTO' | 'SETOR';
  userRole: 'ADMIN' | 'CONVIDADO';
}

export const ResourceRegister: React.FC<ResourceRegisterProps> = ({ type, userRole }) => {
  const [items, setItems] = useState<string[]>([]);
  const [newItem, setNewItem] = useState('');
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  // Delete Modal State
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const config = {
    FILIAL: {
      title: 'Gerenciar Filiais',
      label: 'Nova Filial',
      icon: Building,
      description: 'Cadastre as unidades físicas da empresa.',
      get: dbService.getFiliais,
      add: dbService.addFilial,
      remove: dbService.deleteFilial
    },
    DEPARTAMENTO: {
      title: 'Gerenciar Departamentos',
      label: 'Novo Departamento',
      icon: Layers,
      description: 'Estruture as grandes áreas da organização.',
      get: dbService.getDepartamentos,
      add: dbService.addDepartamento,
      remove: dbService.deleteDepartamento
    },
    SETOR: {
      title: 'Gerenciar Setores',
      label: 'Novo Setor',
      icon: Briefcase,
      description: 'Defina as divisões de trabalho dentro dos departamentos.',
      get: dbService.getSetores,
      add: dbService.addSetor,
      remove: dbService.deleteSetor
    }
  }[type];

  useEffect(() => {
    loadItems();
    setFeedback(null);
    setNewItem('');
    setIsDeleteModalOpen(false);
    setItemToDelete(null);
  }, [type]);

  const loadItems = () => {
    setItems(config.get());
  };

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItem.trim()) return;

    const success = config.add(newItem);
    if (success) {
      setNewItem('');
      loadItems();
      setFeedback({ type: 'success', message: 'Item cadastrado com sucesso!' });
      setTimeout(() => setFeedback(null), 3000);
    } else {
      setFeedback({ type: 'error', message: 'Este item já existe na lista.' });
    }
  };

  // Open the custom delete modal
  const requestDelete = (e: React.MouseEvent, item: string) => {
    e.stopPropagation();
    e.preventDefault();
    setItemToDelete(item);
    setIsDeleteModalOpen(true);
  };

  // Execute the deletion
  const confirmDelete = () => {
    if (!itemToDelete) return;

    setIsProcessing(true);

    // Simulate a small delay for better UX
    setTimeout(() => {
        const success = config.remove(itemToDelete);

        if (success) {
            loadItems();
            setFeedback({ type: 'success', message: 'Item removido com sucesso.' });
        } else {
            setFeedback({ type: 'error', message: 'Erro ao remover item. Tente recarregar a página.' });
        }

        setIsProcessing(false);
        setIsDeleteModalOpen(false);
        setItemToDelete(null);

        setTimeout(() => setFeedback(null), 3000);
    }, 500);
  };

  const Icon = config.icon;

  return (
    <div className="p-6 space-y-6 animate-[fadeIn_0.4s_ease-out]">
        {/* Feedback Toast */}
        {feedback && (
            <div className={`fixed top-6 right-6 z-50 p-4 rounded-xl shadow-2xl border flex items-center gap-3 animate-[slideIn_0.3s_ease-out] ${
                feedback.type === 'success' ? 'bg-white border-green-200 text-green-700' : 'bg-white border-red-200 text-red-700'
            }`}>
                {feedback.type === 'success' ? <CheckCircle2 className="w-5 h-5 text-green-500"/> : <AlertCircle className="w-5 h-5 text-red-500"/>}
                <span className="font-medium">{feedback.message}</span>
                <button onClick={() => setFeedback(null)} className="ml-2 text-slate-400 hover:text-slate-600"><X className="w-4 h-4"/></button>
            </div>
        )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">

        {/* Header */}
        <div className="bg-primary-900 p-6 flex items-center gap-4">
          <div className="p-3 bg-primary-800 rounded-lg">
             <Icon className="w-6 h-6 text-white" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-white">{config.title}</h2>
            <p className="text-primary-200 text-sm">
                {userRole === 'ADMIN' ? config.description : 'Visualização de registros do sistema.'}
            </p>
          </div>
        </div>

        <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-12">

          {/* Left: Add Form - ONLY FOR ADMIN */}
          {userRole === 'ADMIN' && (
            <div className="space-y-6">
               <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-2">
                  <Plus className="w-5 h-5 text-primary-500" />
                  Cadastrar Novo
               </h3>

               <form onSubmit={handleAdd} className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                  <Input 
                     label={`Nome do ${type === 'FILIAL' ? 'Filial' : type === 'SETOR' ? 'Setor' : 'Departamento'}`}
                     value={newItem}
                     onChange={(e) => setNewItem(e.target.value.toUpperCase())}
                     placeholder="Digite o nome..."
                     fullWidth
                  />
                  <button 
                    type="submit"
                    disabled={!newItem.trim()}
                    className="w-full mt-2 flex items-center justify-center gap-2 bg-primary-600 text-white py-3 rounded-lg hover:bg-primary-700 transition-all font-semibold disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-primary-500/20"
                  >
